    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead: If next_item_size fits in post_residual, reward the fit
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New Bin Penalty: Heavily penalize opening new bins unless the fit is perfect
    // or we are near the end of the stream and need to clear space.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Discourage opening a new bin if existing bins can take it
            score += 45.0 + (progress * 20.0);
        } else {
            // Must open a new bin
            score = 0.0;
        }
    } else {
        // 4. Tightness bias: Favor bins that are already "tight"
        // If the bin is getting full, it's safer to keep using it.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 15.0;

        // 5. Global State: If we have many open bins, prioritize packing the tightest ones
        // to avoid fragmentation.
        if open_bins_count > 5 {
            score += (open_bins_count as f64) * 2.0;
        }

        // 6. Avoid "Dead Space": If post_residual is too small for common items (e.g., < 10)
        // and we have many items left, this is a bad fit.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit-Decreasing logic: Penalize large remaining space (fragmentation)
    // We prioritize bins where the post_residual is small.
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead optimization: If the next item fits into the current post_residual,
    // we reward this placement to chain items together.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Pressure management: If we are running out of items, be more aggressive
    // about filling existing bins rather than opening new ones.
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // 4. Dead-space avoidance: If the remaining space is too small to fit any 
    // likely future item (assuming items are >= 10), penalize it.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 5. New Bin Hysteresis: Heavily penalize opening a new bin unless the 
    // existing options are extremely poor (i.e., high post_residual).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to favor consolidation
        score += 40.0;
        // Reduce the penalty if we have many open bins that are nearly full
        score -= (open_bins_count as f64) * 2.0;
    }

    // 6. Global balance: If the current bin's residual is significantly worse 
    // than the mean, penalize it to encourage balancing the bin fill levels.
    if (bin_residual as f64) > mean_residual * 1.2 {
        score += 10.0;
    }

    // 7. Last-chance logic: If this is the only bin that fits the current item, 
    // reward it slightly to ensure we don't prematurely open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

