    // Penalty for leaving small "dead" fragments (1-9) that are hard to fill.
    // We apply a non-linear penalty that spikes as the residual approaches 
    // sizes that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_res) * 5.0;
    }

    // Lookahead coupling: If the next item cannot fit into this post_residual,
    // we penalize the bin choice to favor bins that leave space for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_res) * 2.5;
    }

    // Dynamic density management: As the stream progresses, we become more aggressive 
    // about filling bins tightly to avoid opening new ones late in the process.
    let density_pressure = (1.0 - progress) * (open_bins_count as f64 / 10.0);
    score += density_pressure * post_res;

    // If this is an empty bin (new bin candidate), we only pick it if the 
    // penalties on existing bins are high enough.
    if bin_residual == bin_capacity {
        // Only open a new bin if the fitting bins are forced to create "bad" residuals.
        // We set a threshold cost for opening a new bin.
        score = 45.0 + (progress * 10.0);
    } else {
        // Reward bins that bring the bin closer to the mean residual of the set,
        // promoting uniform filling across the bin population.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.5;
    }

    score
