    // 5. New bin penalty: If this is a new bin (bin_residual == bin_capacity), 
    // only choose it if the existing bins are all very poor fits.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average residual of current bins is worse than 
            // what we would get by starting fresh.
            score = mean_residual * 0.8;
        }
    }

    // 6. Last chance heuristic: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Heavily favor bins where post_residual is small (tight fits).
    // The smaller the post_residual, the better, unless it creates "dead space" (e.g., < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 50.0; // Penalty for creating tiny, likely unusable slivers
    }

    // 2. Lookahead matching: If the next item can fit into the current post_residual,
    // we should prioritize this bin to maximize bin density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0; 
    }

    // 3. Global Bin Management: If this is the only bin that fits the current item,
    // we should prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 4. Mean Residual balancing: Penalize bins that deviate significantly from the 
    // current mean residual to keep bin fill levels uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.5;

    // 5. New Bin Thresholding: If we are considering a new bin (bin_residual == bin_capacity),
    // only accept if all existing bins are poorly suited.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low,
        // suggesting that existing bins are full and we need a fresh start.
        if mean_residual > 20.0 {
            score = 10.0; // Moderate priority to open new bin
        } else {
            score = 100.0; // High penalty to discourage opening new bin prematurely
        }
    }

    // 6. Progression normalization: As the stream nears the end, become more aggressive 
    // about fitting items into existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often better to have used a different bin or opened a new one.
    // We penalize small residues that are too small to fit future items.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if the next item is large, favor keeping larger bins open.
    // If the current bin is the only one that can fit the current item, 
    // we penalize the "New Bin" option heavily to prevent unnecessary fragmentation.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to how much room we have elsewhere.
        score += 10.0 + (mean_residual * 0.5);
        if next_item_size > 0 && next_item_size < 50 {
            score -= 5.0; // Encourage early new-bin usage if future item is small
        }
    } else {
        // If this bin is the last chance for the current item, reward it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Non-linear coupling: as we reach the end of the stream, 
        // prioritize minimizing open_bins_count to reduce total bin count.
        score += (open_bins_count as f64) * progress * 2.0;
    }

    // Smooth transition: penalize bins that deviate significantly from the mean_residual
    // to encourage uniform bin filling.
    let residual_diff = (post_res - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
