        let fragmentation_penalty = if post < 10.0 && post > 0.0 { 25.0 - post } else { 0.0 };

        // Reward bins that align with the lookahead (next_item_size)
        // If next_item_size fits in the post_residual, reduce the score.
        let lookahead_bonus = if next_item_size > 0 && post >= next_item_size as f64 {
            (post - next_item_size as f64) * 0.5
        } else {
            0.0
        };

        // Coupling: Use mean_residual to balance load across bins (avoid creating "islands")
        let load_balance = (post - mean_residual).abs() * 0.1;

        post + fragmentation_penalty - lookahead_bonus + load_balance
    };

    // If this is the last chance for this item, reduce penalty for poor fit
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

