    // 4. Harmonic Alignment: Reward post_residuals that are multiples of 25 (common capacity fractions).
    if post_residual % 25 == 0 {
        score -= 15.0;
    }

    // 5. Density Balancing: If we are late in the stream, favor tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // 6. Last Chance Logic: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
