    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0) * (post_residual as f64 / bin_capacity as f64);

    // 5. New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // other bins could have taken the item. Only open a new bin if the current fit 
