}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin early in the stream, but allow it if it's the only option.
    // The "is_new" boolean represents the case where the bin is currently empty.
    let is_new = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new { 
        (1.0 - progress) * 45.0 + (fitting_bins_count as f64 * 15.0) 
    } else { 
        0.0 
    };

    // Objective: Minimize post_residual (Best Fit), but penalize creating "dead zones"
    // (space too small for most items). 
    // We use a quadratic penalty for the post_residual to favor tight packing.
    let base_score = post * post / 100.0;

    // Lookahead logic: if the next item is large, avoid leaving a residual that is 
    // just slightly smaller than the next_item_size.
    let mut lookahead_penalty = 0.0;
    if next_item_size > 0 && post < next_item_size as f64 {
