    // Interaction term: As the stream progresses, prioritize closing bins (lower mean_residual)
    // to consolidate space.
    let consolidation_bonus = (mean_residual - post) * progress * 0.5;

    base_score + new_bin_penalty + lookahead_penalty - consolidation_bonus
}

