    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 1.5) + (mean_residual * 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are too small to fit common items
    // but too large to be considered "full". We penalize [1, 9] specifically as "orphaned" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bins Pressure: If we have many open bins, prioritize filling them tightly.
    // If we have few open bins, we are more tolerant of opening a new one.
    score += (open_bins_count as f64) * 2.5;

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, 
    // reward this placement heavily to encourage "perfect packing" pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. New Bin Bias: Increase the score of a new empty bin (bin_residual == bin_capacity)
    // to discourage starting a new bin unless the existing options are truly poor.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // 6. Mean Residual Balancing: Penalize bins that deviate significantly from the mean 
    // to keep the packing density uniform across all active bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward tight packing: If post_residual is small, it's a good fit.
    // 2. Penalty for creating "dead space": If post_residual is between 1 and 9, 
    //    it's unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead Logic: If the next item can fit perfectly or near-perfectly 
    //    into the remaining space, prioritize this bin.
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        if diff >= 0 && diff < 5 {
            score -= 30.0; // Strong reward for potential perfect fit
        } else if diff < 0 {
            score += 15.0; // Penalty if next item is blocked
        }
    }

    // 4. Global balance: If this is the only bin that fits the item (fitting_bins_count == 1),
    //    we should be careful about opening a new bin. 
    //    If bin_residual == bin_capacity (New bin case), add a heavy penalty 
    //    unless we are forced to open one.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0; // Discourage opening new bins if others are available
        } else {
            score -= 10.0; // Neutralize for forced new bin
        }
    }

    // 5. Residual Alignment: Prefer bins that stay close to the mean residual 
    //    to keep the load balanced across open bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 6. Progress weighting: As the stream nears the end, prioritize closing bins
    //    (lower residual) over spreading items out.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize leaving 
    // small slivers (e.g., 1-9) that are unlikely to be filled.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // reward this placement to maximize bin density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / 100.0);
    }

    // 3. Global State Balancing: If current bin is emptier than the average of all 
    // open bins, penalize it to encourage consolidation into tighter bins.
    if (bin_residual as f64) > mean_residual {
        score += 15.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // 4. New Bin Logic: Only open a new bin if the current fit is extremely poor 
    // relative to the remaining space or if we are nearing the end of the stream.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to favor packing into existing ones.
        score = 40.0 + (progress * 20.0);

        // If we have many open bins that are nearly full, don't open a new one.
        if open_bins_count > 5 {
            score += 30.0;
        }
    } else {
        // If this is the only bin that fits the item, make it very attractive.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the square of the post_residual (Best Fit Decreasing logic).
    // Squaring penalizes large gaps more heavily than small ones.
    let mut score = post * post;

    // Favor bins that align with the mean residual to keep distribution uniform.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // Lookahead: If the next item is large, penalize small post_residuals 
    // that leave no room for the upcoming item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 2.0;
        }
    }

    // Dynamic thresholding for new bins:
    // If the bin is new (bin_residual == bin_capacity), apply a penalty that 
    // scales with progress and the number of currently open bins.
    if bin_residual == bin_capacity {
        // As the stream progresses, we want to be more "desperate" to reuse open bins.
        // Penalty for opening a new bin increases as we near the end of the stream.
        let new_bin_penalty = 1500.0 * (1.0 + progress) + (open_bins_count as f64 * 50.0);
        score += new_bin_penalty;
    } else {
        // If it's a tight fit (the last fitting bin), reward it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
    }

    // Apply a mild non-linear dampening to prevent extreme values at the start of the stream
    score * (1.0 + (progress * 0.2))
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (small residuals that cannot accommodate common items)
    // We penalize residuals that are too small to fit the average item size (roughly 30-40) 
    // but large enough to be wasted (5-15).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is slightly smaller than next_item_size, we punish this bin heavily.
    if next_item_size > 0 && post_residual < next_item_size {
