    }

    // 4. New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // only accept it if the current open bins are all very poor fits (high post_residual).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 30.0 {
            // New bins are expensive; penalize them unless the average quality of open bins is low.
            score += 10.0;
        } else {
            score += 60.0;
        }
    }

    // 5. Modulo-based density encouragement: 
    // Reward packing items that result in residuals close to 0 (perfect fit) or 
    // multiples of 25 (allowing for common item size quartiles).
    let fit_remainder = post_residual % 25;
    if fit_remainder < 5 {
        score -= 15.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
