    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 4. Distribution balancing: Penalize deviating too far from the mean_residual of all open bins.
    // This keeps bins filled at similar levels to maximize future capacity flexibility.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. New bin management: If bin_residual == bin_capacity, this is a proposal to open a new bin.
    // Only choose this if the penalty for fitting into existing bins is extremely high.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already, or if existing bins are very full.
