    //    or divisors of capacity (e.g., 20, 25, 33, 50).
    let harmonic_penalty = match post_residual {
        0 => -50.0,    // Perfect fit reward
        r if r % 25 == 0 => -15.0,
        r if r % 20 == 0 => -10.0,
        r if r > 70 => 40.0, // Avoid creating unusable small-capacity bins
        _ => 0.0,
