    // 4. Scarcity management: If this is the last bin that can fit the item, 
    //    heavily prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. New bin thresholding: If evaluating an empty bin (bin_residual == bin_capacity),
    //    apply a high cost to prevent opening new bins unless all other options are poor.
    if bin_residual == bin_capacity {
        score += 45.0; 
