    // Lookahead logic: if next_item_size fits in the post_residual, reward this bin.
    let lookahead_reward = if next_item_size > 0 && post >= next_item_size as f64 {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty that
    // decreases as the stream progresses (to allow more bins later on).
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 * (1.0 - progress.powi(2))
    } else {
        0.0
    };

    // Coupling: If fitting_bins_count is low, we are running out of options;
    // strongly prefer filling existing bins over opening new ones.
    let urgency_factor = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -40.0
    } else {
