    };

    let mut score = post + fragmentation_penalty + lookahead_reward + new_bin_penalty + urgency_factor;

    // Favor bins that align with the current mean residual to keep bin states uniform.
    score += (post - mean_residual).abs() * 0.5;

    score
}

