pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Core objective: Minimize post_residual (Best Fit).
    // Penalize creating "dead zones" (residuals too small to fit common items).
    // A residual between 1 and 9 is often unusable (given min item size is 10).
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        100.0 * (10.0 - post)
    } else {
        0.0
    };

    // Lookahead logic: If the next item is large, we want to prioritize keeping 
    // larger residuals open. If next_item_size is 0 (end of stream), we prioritize
    // emptying current bins (Best Fit).
    let lookahead_bias = if next_item_size > 0 {
        let fit_next = if post >= next_item_size as f64 { 0.0 } else { 50.0 };
        fit_next * (1.0 - progress)
    } else {
        0.0
    };

    // Encourage using existing bins over new bins as the stream progresses
    // to avoid fragmentation at the end of the stream.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 5.0) + (progress * 100.0)
    } else {
        0.0
    };

    // Coupling: Use mean_residual to prevent over-packing one bin 
    // while others remain mostly empty.
    let balance_factor = (post - mean_residual).powf(2.0) * 0.1;

    let score = post + dead_space_penalty + lookahead_bias + new_bin_penalty + balance_factor;

    score
