    let new_bin_penalty = 15.0 + (progress * 25.0);

    // 5. New Bin Candidate Handling:
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or very few fitting options.
        // This discourages fragmentation early on.
        score = new_bin_penalty + (open_bins_count as f64 * 2.0);
    } else {
        // 6. Fitting Constraint: If this is the only bin that fits the item, make it very attractive.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // 7. Density Balancing: Penalize bins that deviate significantly from the mean residual.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for any future item.
    // If post_residual is small but > 0, it's often better to have it be 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead matching: If the next item fits perfectly into the post_residual, 
    // highly reward this bin (Best-Fit-Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Balance usage: Penalize bins that deviate significantly from the mean residual.
    // We want to keep open bins at similar fill levels to maximize packing flexibility.
    let residual_dev = (post_residual as f64 - mean_residual).abs();
    score += residual_dev * 0.2;

    // 4. Thresholding: If this is the only bin that fits the item, make it very attractive
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 5. New Bin logic: If bin_residual == capacity, we are evaluating a NEW bin.
    // We only want to open a new bin if the current open bins are "too full" or 
    // "too fragmented" (high mean_residual penalty).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless existing bins are very full.
        score += 40.0;
        score += (open_bins_count as f64) * 5.0;
    }

    // 6. Progress factor: As we approach the end of the stream, prioritize tight fits
    // to close out open bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize creating "dead space" (small residuals that are unlikely to fit future items)
    // We heavily penalize residuals between 1 and 9, as they are mostly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead logic: If the next item doesn't fit in the current post_residual, 
    // we penalize the current choice to preserve the space for other bins.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward fits that leave room for the next item
            score -= 10.0;
        }
    }

    // 3. Dynamic Threshold for opening new bins:
    // As we approach the end of the stream, be more conservative about opening new bins.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty for opening a new bin if existing bins can fit the item.
            // This penalty scales with how many bins are already open to discourage fragmentation.
            score += 40.0 + (open_bins_count as f64 * 2.0) + (progress * 20.0);
        }
    } else {
        // 4. Best-Fit refinement: 
        // If the bin is not new, prioritize bins that are already "tight" (low residual).
        // We subtract the post_residual to favor filling bins as much as possible.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;

        // If this bin is the last one that can fit the item, reward it to prevent 
        // unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // 5. Global state balancing:
    // If the current bin is significantly emptier than the mean, penalize it 
    // to encourage consolidating items into fuller bins.
    if (bin_residual as f64) > mean_residual {
        score += 5.0 * (bin_residual as f64 / mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post;

    // Penalty for opening a new bin:
    // If bin is empty (new bin candidate), we apply a dynamic penalty based on progress.
    // Early in the stream, we are more conservative (higher penalty).
    // Late in the stream, we are more permissive to finish off items.
    if bin_residual == bin_capacity {
        score += 25.0 + (35.0 * (1.0 - progress));
    }

    // Lookahead logic (k=2):
    // If the next item exists and cannot fit into the current post_residual,
    // we penalize the current choice to favor bins that leave enough room for it.
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 40.0 * (1.0 - (post / 100.0));
    }

    // Efficiency coupling:
    // Penalize placements that create "dead space" (small residuals that are hard to fill).
    // We penalize residuals in the 1-15 range more heavily as they are difficult to reuse.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.0;
    }

    // Contextual awareness:
    // If this is the only fitting bin, reduce the penalty for poor fits to prevent
    // unnecessary new bin creation if the fit is "acceptable".
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Global density pressure:
    // If we have many open bins, encourage consolidation by penalizing high mean_residual.
    score += (mean_residual * 0.2) * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "unusable" space (too small for most items)
    // We prioritize keeping residuals in ranges that can accommodate the next item or common item sizes
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: if the next item can fit in the post_residual, lower the score
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic/Modulo logic: prioritize filling bins to specific thresholds
    // Bins with residuals divisible by 20 are often more versatile for the 10-80 distribution
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless we have no other choice (fitting_bins_count == 0)
    if bin_residual == bin_capacity {
