        }
    }

    // Reward bins that have residuals close to the global mean to maintain uniformity
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Favor bins that are already "tight" if we are late in the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 15 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residuals that are too small to fit typical future items.
    // If post_residual is in the "dead zone" (1..9), it is highly unlikely to accommodate future items (10..100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bins Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin, apply a heavy penalty proportional to the current open_bins_count.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Integration: If the next item cannot fit in this bin's post_residual,
    // penalize the choice to save the bin for a potentially better fit later.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the current item,
    // significantly lower the score to prioritize filling it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean Residual Balancing: Favor bins that stay close to the current average utilization
    // to keep bins packed consistently rather than fragmenting space.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing with a lookahead penalty.
    // We prioritize bins that result in a post_residual that perfectly complements the next_item_size.
    // If we are forced to open a new bin, we penalize it heavily unless the current open bins are very full.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // Only open a new bin if the existing bins are already quite full (mean_residual is low)
        // or if we have very few fitting options.
        score += 25.0 + (mean_residual * 0.5);
    } else {
        // Penalty for creating "slivers" (unusable space < 10)
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }

        // Lookahead: reward bins that leave exactly enough room for the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                let diff = (post_residual - next_item_size) as f64;
                // Reward tighter fits for the next item
                score -= (100.0 - diff) * 0.1;
            } else {
                // Penalize if this bin will definitely not fit the next item
                score += 5.0;
            }
        }
    }

    // Encourage filling bins that are already partially full to keep the number of bins low
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Discourage spreading items too thin
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

