    // If post_residual is very small, it's either perfect or a "sliver" (bad).
    // We treat slivers (< 10) as high-penalty unless they are 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    } else if post_residual == 0 {
