    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // 5. Scarcity Handling: If this is the only bin that can fit the item, 
    // lower the score to ensure we don't accidentally prefer a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

