    // 3. Global balance: Prefer bins closer to the mean residual to keep packing density uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    // 4. Scarcity: If this is the only bin that fits, we are forced to take it.
