    // We heavily penalize residuals between 1 and 9 as they are difficult to use.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // Dynamic Lookahead Coupling:
    // If we have a next item, penalize bins that cannot fit the next item after this one.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Adaptive New Bin Threshold:
    // As the stream progresses, discourage opening new bins unless the fit is very tight.
    if is_new_bin {
        // High base cost for opening a new bin, which decays as we reach the end of the stream
        // to ensure we don't leave many half-empty bins at the final steps.
        score += 45.0 * (1.0 - (progress * 0.5));

        // If we have many open bins, penalize opening another one significantly.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // Reward bins that bring the residual closer to the global mean,
        // promoting uniform bin utilization.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Encourage filling up bins that are "almost full" (fitting_bins_count logic)
    // If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward Best-Fit behavior (tightness)
    // Minimizing post_residual is standard Best-Fit, but we penalize tiny gaps (1-4)
    // that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // 2. Lookahead Harmonic Coupling
    // If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Harmonic Class Logic
    // Penalize bins that leave a residual that is "hard" to fill (e.g., small prime residues)
    // and reward those that leave a multiple of 10, which aligns with common item sizes.
    if post_residual % 10 != 0 {
        score += 5.0;
    }

    // 4. Threshold Logic for New Bin
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already (avoid fragmentation)
        // or if the current item is very large (e.g., > 70) and would force a bad fit elsewhere.
        if item_size > 70 {
            score -= 10.0;
        } else {
            score += 40.0; // Strong penalty for opening new bins unnecessarily
        }
    }

    // 5. Global Density Adjustment
    // As the stream progresses, favor packing tighter to close out bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (mean_residual / bin_capacity as f64);

    // 6. Avoid "Last Chance" Trap
    // If this is the only bin that fits the current item (fitting_bins_count == 1),
    // and the post_residual is very high (meaning we waste a lot of space),
    // we might prefer to open a new bin if the next item is large.
    if fitting_bins_count == 1 && post_residual > 60 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Heavily penalize small, unusable gaps (1-9).
    // Gaps between 1 and 9 are almost always unfillable given item constraints (10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the current fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty to force reuse of existing bins.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Efficiency: If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // 5. Residual Balance: Penalize bins that deviate significantly from the mean residual.
    // This promotes filling bins at a similar rate to keep the system balanced.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 6. Final scaling for late-stream cleanup: Be more aggressive in closing bins as the stream nears the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost: The tighter the residual, the better (Best-Fit principle).
    let mut score = post_residual as f64;

    // 2. Lookahead optimization: If the post_residual can perfectly or nearly accommodate the next item, reward it.
    // We prioritize bins that leave exactly enough room for the next item (post_residual == next_item_size).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            // Penalize large gaps that couldn't fit the next item, scaled by how much space is wasted.
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Cannot fit next item, slight penalty to prefer bins that can.
            score += 10.0;
        }
    }

    // 3. Global balance: If this bin's residual deviates significantly from the mean, we penalize it 
    // to keep bins balanced, preventing "bin fragmentation" where some are very full and others are very empty.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 4. Threshold management: If this is the last chance for the item (fitting_bins_count == 1),
    // and the post_residual is very small (e.g., < 10), it's likely a good placement ("closing" a bin).
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 25.0;
    }

    // 5. New bin penalty: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We penalize opening a new bin significantly unless we are forced to or the fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "slivers" (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next_item fits in post_residual, prioritize this bin strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Reward tighter fit for the pair
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // Global state: if we are near the end of the stream, be more aggressive
    // about using existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if there are existing options
            score += 35.0 + (progress * 20.0);
        } else {
            // We must open a new bin, neutralize the base score
            score = 0.0;
        }
    } else {
        // Favor bins that align with the global mean residual to keep distribution uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Dynamic threshold: As we approach the end, prioritize filling bins completely
    if progress > 0.8 {
        score += post_residual as f64 * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow flexibility as the stream ends
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress).powf(0.5) * 40.0 + 10.0
    } else {
        0.0
    };

    // Calculate "tightness" score: post_residual is the space remaining.
    // We want to minimize this, but we penalize values that are too small to fit common items (dead space).
    // Small post_residual (e.g., 1-5) is often worse than a slightly larger residual (e.g., 10-15)
    // because it creates unusable gaps.
    let tightness_penalty = if post_residual < 10 && post_residual > 0 {
        (10.0 - post_residual as f64) * 2.5
    } else {
        0.0
    };

    // Lookahead interaction: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we effectively lose the ability to place the next item there.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_residual as f64) * 0.8
    } else {
        0.0
    };

    // Global state awareness: If we have many fitting bins, be more selective to keep mean_residual high.
    let dispersion_bonus = (mean_residual - post_residual as f64).abs() * 0.2;

    let mut score = post_residual as f64 
        + tightness_penalty 
        + new_bin_penalty 
        + lookahead_penalty 
        + dispersion_bonus;

    // If this is the last chance for this item (fitting_bins_count == 1), 
    // significantly reduce the score to ensure we don't open a new bin unnecessarily.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize post_residuals that are small but non-zero (fragments)
    // We favor tight fits (post_residual -> 0) or large residuals (leaving room for future big items).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0; 
    }

    // 2. Lookahead Coupling: If a next item exists, penalize placements that make it impossible to fit
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This placement creates a "dead zone" for the next item
            score += 40.0;
        } else {
            // Reward placements that leave exactly enough or more for the next item
            score -= 10.0;
        }
    }

    // 3. Efficiency Thresholding: If we are nearing the end of the stream, favor finishing bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 10 {
        score -= 30.0;
    }

    // 4. Bin Management: Avoid opening new bins unless the fit is catastrophic in existing ones.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy baseline penalty
    // unless the mean_residual is already very low (indicating we are packing tightly).
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    }

    // 5. Harmonic Class Balance: Balance the load across bins
    // Penalize if we have many open bins and this bin's residual deviates from the mean
    if open_bins_count > 1 {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 6. Last Chance Logic: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residual ranges that are too small for common items (< 10)
    // but large enough to waste capacity. If post_residual is in (0, 10), it is "fragmented" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open bins pressure: If we have many open bins, penalize opening a new bin (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
