        // If we are near the end of the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 4. Fitting constraints: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Global efficiency: Favor bins that stay closer to the mean residual of the current set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base penalty: The remaining space after placement (post_residual).
    let mut score = post_residual as f64;

    // 2. Lookahead Penalty: Penalize placements that leave a gap too small for the next item.
    // If the next item exists, we penalize if post_residual is slightly smaller than next_item_size,
    // as this forces fragmentation.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Significant penalty for creating a bin that cannot accommodate the next known item.
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward if the current placement leaves a perfect fit for the next item.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Global State Balancing:
    // If this is a brand-new bin (bin_residual == bin_capacity), apply a heavy penalty
    // proportional to the number of bins already open to discourage fragmenting the bin space.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // Also penalize opening a new bin if other bins could have fit the item.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Tightness Calibration:
    // Favor bins that align with the global mean residual to keep bin states uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Progression Scaling:
    // As we approach the end of the stream, prioritize aggressive packing (minimizing residual)
    // to avoid leaving many half-empty bins at the end.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
