        }
        // Baseline cost of a new bin is constant but scales with remaining items.
        score += 25.0;
    } else {
        // Reward placements that leave the bin residual close to the average,
        // promoting uniform packing density across bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // Lookahead: If next item exists, penalize placements that leave too little space 
        // for it, but reward those that leave exactly enough space.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // Potential dead space penalty: bin becomes hard to fill later.
                score += (next_item_size - post_residual) as f64 * 1.2;
            } else if post_residual == next_item_size {
