}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We penalize small post_residuals that are too small to fit common future items (10-40 range)
    // but reward configurations that balance the bin capacity relative to the mean_residual.
    let mut score = post;

    // Penalty for creating "dead zones": residuals between 1 and 9 are often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Coupling with stream progress: As the stream nears the end, become more aggressive 
    // about packing into existing bins to avoid opening new ones.
    let fill_efficiency = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= progress * 15.0 * fill_efficiency;

    // Lookahead logic: If the next item is large, favor bins that leave enough space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Heuristic for new bin creation: 
    // If we are forced to open a new bin, the score should be higher than a tight fit,
    // but lower than a very poor fit (e.g., a bin with 1-9 space remaining).
    if bin_residual == bin_capacity {
        score = 12.0 + (progress * 5.0);
    }

    // Adjust based on the density of the current packing state.
    // If the mean residual is high, we have plenty of space; be more selective.
    score += (mean_residual / 10.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

