    // but too large to be considered "tight". If post_residual is in (0, 10), it's dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If next_item_size is known, favor bins where the remaining space
    // is a "harmonic match" for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that fit the next item perfectly (modulo 5 alignment)
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize bins that force a new bin for the next item
            score += 30.0;
        }
    }

    // 3. Global Density Balancing: If we have many open bins, prioritize filling the tightest one.
    // Otherwise, keep residuals balanced around the mean to prevent fragmented bin clusters.
    let residual_variance = (bin_residual as f64 - mean_residual).abs();
    score += residual_variance * 0.2;

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize based on current fragmentation.
    // Only open a new bin if the current open bins are all very poorly suited for the current item.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score += 45.0;

        // If we have many bins already, make opening a new one much more expensive
        score += (open_bins_count as f64) * 5.0;

        // If we are near the end of the stream, discourage new bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // Reward bins that have high utilization
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Critical Constraint: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the remaining space is too small to fit any likely future items (e.g., < 10),
    // we penalize it heavily to force packing into bins that leave room for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item can fit in the remaining post_residual, 
    // reward this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: If we have many open bins, penalize opening a new one 
    // (identified by bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
