        // If this is a new bin, penalize based on how many other bins could have accepted the item.
        score += (fitting_bins_count as f64) * 10.0;
    }

    // 4. Mean Residual Balancing: If the current bin is "emptier" than the average open bin,
    // we prefer filling it to reduce the total number of under-utilized bins.
    if (bin_capacity - bin_residual) < (bin_capacity as f64 - mean_residual) as u32 {
        score -= 10.0;
    }

    // 5. Urgency: As we reach the end of the stream, prioritize closing bins 
    // (low post_residual) over keeping them open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but prioritize fits that leave space for next_item_size.
    // We penalize leaving "dead space" (small residuals that cannot fit common items).
    // An empty bin (bin_residual == bin_capacity) is treated as a baseline to compare against.

    let mut score = post_residual as f64;

    // 1. Prioritize bins where post_residual perfectly matches the lookahead item (Best Fit + Lookahead)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // Strong incentive for perfect future fit
        } else if post_residual >= next_item_size && post_residual < (next_item_size + 10) {
            score -= 15.0; // Moderate incentive for "good enough" future fit
        }
    }

    // 2. Penalize creating "fragmented" bins (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 3. Dynamic thresholding based on stream progression
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual > 20 {
