    // At the end of the stream, we want to minimize the number of open bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // 4. Global State: If the bin is already quite empty (high mean_residual), 
    // try to keep new items out of it to avoid fragmenting the space.
    if mean_residual > 50.0 && bin_residual < bin_capacity {
