    }

    // 5. New Bin Logic: If we are forced to open a new bin, make it expensive unless
    // the current alternatives are all very poor fits.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score = 40.0;
        // If we are near the end, opening a new bin is very expensive.
        score += 60.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
