        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Open Bin Pressure: If we have many bins open, penalize opening a new one significantly.
    // If bin_residual == bin_capacity, this represents opening a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 15.0);
        // If there are other bins that could fit the item, opening a new one is highly discouraged.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 3. Lookahead Optimization: If the next item exists, favor bins that leave enough room for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= (post_residual as f64 - next_item_size as f64) * 0.5;
        } else {
            // Penalize bins that would force a new bin for the next item
            score += 10.0;
        }
    }

    // 4. Mean Residual Balancing: Prefer bins that keep the mean residual stable.
    // If current residual is much higher than the mean, we are likely wasting space.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tightly packed.
    // 2. Lookahead Synergy: Reward placements where post_residual matches next_item_size.
    //    We subtract the match quality to lower the score (prioritize).
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 50.0 / (1.0 + diff);
    }

    // 3. Fragmentation Control: Penalize creating "dead zones" (post_residual < 10) 
    //    if the item_size is large, as these small residuals are rarely useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Mean Residual Balancing: Bias towards bins that keep the global average 
    //    residual balanced to prevent "bin starvation" or excessive open bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 5. New Bin Thresholding: If this is an empty bin, add a penalty based on 
    //    the number of open bins to encourage packing into existing bins first.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.0);
    }

    // 6. Last Chance Logic: If this is the only bin that can fit the item, 
    //    heavily discount the score to ensure we don't accidentally open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 7. Progression scaling: As we approach the end of the stream, 
    //    become more aggressive about closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to how much capacity we would waste
    // by not using existing bins, scaled by progress to be more conservative at the end.
    if is_new_bin {
        score += (bin_capacity - item_size) as f64 * (1.5 - progress);
        if fitting_bins_count > 0 {
            score += 40.0; // Strong penalty for opening new bin if space exists
        }
    } else {
        // Reward fitting into bins that are already "tight"
        // If post_residual is very small (near 0), it's a high-quality packing.
        if post_residual < 10 {
            score -= 15.0;
        }

        // Lookahead heuristic: If the next item fits into this post_residual, 
        // we reward this bin to avoid creating fragmented space.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }

        // Penalize bins that deviate significantly from the mean_residual,
        // as maintaining uniform bin usage helps keep options open for larger items.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Dynamic threshold: As we approach the end of the stream, prioritize 
    // closing bins (lower post_residual) over keeping them open.
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tight fits (smaller post_residual)
    let mut score = post.powf(1.5);

    // Penalize the new bin candidate (bin_residual == bin_capacity) 
    // to force utilization of existing bins, unless progress is high and fit is poor.
    if bin_residual == bin_capacity {
        // As we reach the end of the stream, lower the barrier to starting a new bin
        // to avoid "trapping" large items in poor fits.
        score += (85.0 * (1.0 - progress)) + (mean_residual * 0.5);
    } else {
        // If this is the last chance to fit the item in an existing bin,
        // reward it heavily to avoid opening a new one prematurely.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Lookahead coupling: if the next item is large, avoid leaving a residual
    // that is just slightly too small to fit that item.
    if next_item_size > 0 {
        let gap = post_residual as i32 - next_item_size as i32;
        if gap < 0 && gap > -15 {
            // Penalize creating a "near-miss" bin for the next item
            score += 50.0 * (1.0 - (gap.abs() as f64 / 15.0));
        }
    }

    // Smooth coupling with mean_residual to prevent variance in bin fill levels
    // Reward bins that keep the overall mean residual stable
    score += (post - mean_residual).powi(2) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Best-Fit logic: prioritize small post_residual (already in score)
    // 2. Harmonic Penalty: Penalize residuals that create 'unusable' gaps (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
