    }

    // 4. Scarcity Logic: If this is the only bin that fits the current item, prioritize it heavily
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // 5. New Bin Thresholding: 
    // If we are considering opening a new bin (bin_residual == bin_capacity), 
    // only do so if the mean residual is high enough to suggest we have too many fragmented bins.
    if bin_residual == bin_capacity {
