            score += 100.0; // Penalty for opening new bins when current ones are relatively empty
        } else {
            score -= 10.0; // Encourage opening a new bin to preserve better-fitting space elsewhere
        }
    }

    // 6. Modulo Harmonic Weighting: 
    // Create 'buckets' to prefer residuals that are multiples of 20 (favorable for common item sizes)
    let remainder = post_residual % 20;
    score += (remainder as f64) * 0.5;

    // 7. Progression Scaling: As the stream nears the end, become more aggressive about fitting
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1..9), it is likely to become 
    // permanently unusable, as item sizes are generally >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item can fit in the remaining space, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
