    }

    // 3. Open Bins Pressure: Penalize opening new bins when many are already open,
    // but reward using existing bins to keep the count low.
    if bin_residual == bin_capacity {
        // This is a new bin candidate
        score += (open_bins_count as f64) * 2.0;
        // If we have other options, discourage opening a new bin unless necessary
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // Reward filling existing bins to improve consolidation
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Mean Residual Alignment: Penalize bins that deviate significantly from the mean 
    // to encourage uniform packing density across open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: prioritize bins that leave the smallest residual.
    // However, avoid creating "dead zones" (residuals too small for any likely future item).
    // If post_residual is very small but > 0, it is often better than a large residual.

    // 2. Lookahead Coupling: If the next item fits perfectly into this bin's post_residual,
    // we heavily reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 50.0 / (1.0 + diff);
    }

    // 3. Penalty for fragmentation: If the post_residual is small (e.g., < 10), 
    // it effectively becomes unusable dead space. 
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Mean Residual Balancing: If this bin's residual is significantly better 
    // than the average of other bins, prioritize it to keep the bin distribution tight.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. New Bin Thresholding: If we are forced to open a new bin, we only do so if
    // the current fitting options are all "poor" (defined as leaving a large residual).
    if bin_residual == bin_capacity {
        // If we have many bins already open, discourage opening a new one unless 
        // the current fit is absolutely terrible.
        score = 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If this is the only bin that fits, we must take it, but we adjust the 
        // score to reflect how "tight" the fit is.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // 6. Progress weighting: As the stream nears completion, become more aggressive 
    // about closing bins (minimizing total bins used).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
