pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals that are "near-misses" for future items.
    // If we leave a tiny sliver (1-9), it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Logic: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than the next item, we penalize the current choice.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 35.0;
    }

    // 3. Harmonic Filling: Encourage filling bins to specific thresholds (e.g., 80%, 90%).
    // If we reach a state where the bin is very full, reward it to consolidate space.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.85 {
        score -= 20.0;
    }

    // 4. New Bin Threshold: Discourage opening a new bin unless the current fit is terrible.
    // If this is a new bin (bin_residual == bin_capacity), add a high base cost.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already or if the fit is bad.
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Fitting Constraint: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Mean Residual Balancing: Avoid creating bins that deviate significantly from the mean.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: Heavily penalize residuals that are too small to fit any likely subsequent items.
    // Given the range 10..100, residuals < 10 are highly likely to be "dead" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Open bins pressure: As the stream progresses, discourage opening new bins (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // Increase penalty for opening new bins as we reach the end of the stream
        score += (step_index as f64 / total_items as f64) * 30.0;
    }

    // 4. Fitting scarcity: If this is the only bin that can fit the item, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Mean residual balance: Discourage bins that deviate significantly from the mean, preventing uneven distribution.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Aggressive 2-step lookahead matching
    // Objective: Minimize post_residual, but heavily penalize splits that make future packing difficult.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // High penalty for opening a new bin if we have space elsewhere.
        // We only open a new bin if the current open bins are "too full" to accommodate the lookahead.
        score = 80.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Reward placements where the remaining space (post_residual) 
        // is close to the next_item_size to prevent fragmentation.
        if next_item_size > 0 {
            let diff = (post_residual as f64 - next_item_size as f64).abs();
            score += diff * 0.4;
        }

        // Penalize placing into a bin if it significantly deviates from the mean_residual
        // to keep bin levels balanced.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.2;

        // If this is the last chance for this item (fitting_bins_count == 1),
        // we prioritize this bin to avoid opening a new one later.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Progression weight: as we near the end of the stream, prioritize tight packing
    // more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize configurations that leave small, unusable gaps.
    // Gaps < 10 are generally difficult to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Integration: If the next item can fit in the post_residual,
    // we prioritize this bin to preserve the packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Global State: If we are nearing the end of the stream, prioritize 
    // filling current bins to avoid leaving stranded bins.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. New Bin Thresholding: 
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is already very low
        // or if we have very few fitting options.
        if fitting_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0;
        }
    }

    // 5. Fragmentation Avoidance:
    // Penalize opening a new bin if we have many empty/near-empty bins.
    if bin_residual == bin_capacity && open_bins_count > 5 {
        score += 20.0 * (open_bins_count as f64 / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating "slivers" (dead space < 10)
    // Small residuals are hard to fill later, especially as the stream progresses
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0 * (1.0 + progress);
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to increase packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamic thresholding for new bin creation:
    // As the stream progresses, we want to be more aggressive in filling existing bins 
    // (reducing the attractiveness of opening new bins).
    if is_new_bin {
        // Base cost for opening a new bin is high to discourage fragmentation
        score += 45.0 * (1.0 + progress);

        // If many bins can already fit the item, opening a new one is inefficient
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 20.0;
        }
    } else {
        // Reward bins that have residuals closer to the mean_residual of open bins
        // to keep the "filling level" uniform across the bin set.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Final scaling: favor bins that are nearly full towards the end of the stream
    score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

