    // Residuals between 1 and 14 are notoriously difficult to fill later.
    if post_residual > 0 && post_residual < 15 {
        score += 45.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is known, favor bins that accommodate it.
    // If post_residual is slightly less than next_item_size, we create a bad state.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 30.0;
        } else {
            // Reward bins that leave exactly enough space for the next item (tight fit)
            let diff = post_residual - next_item_size;
            if diff < 10 {
                score -= 15.0;
            }
        }
    }

    // 3. Adaptive Thresholding: If we are late in the stream, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we progress through the stream.
        score += 25.0 + (progress * 50.0);
        // If we have many open bins, penalize opening another one.
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. Harmonic Alignment: Favor placing items in bins that align with the current mean residual.
    // This helps keep bin fullness uniform.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is often unusable.
    // We penalize these gaps heavily to encourage "perfect" or "large-gap" fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bin Pressure: If we have many open bins, we should be more aggressive about 
    // filling them rather than opening new ones, unless the fit is catastrophic.
    score += (open_bins_count as f64) * 0.5;

    // 3. Lookahead Logic: If the next item is large and this bin can't fit it, 
    // prioritize leaving this bin for the current item if it results in a better overall mean_residual.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. New Bin Threshold: If this is a new bin (bin_residual == bin_capacity), 
    // only choose it if the fitting_bins_count is low or the current state is sub-optimal.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing options.
            score += 60.0 + (fitting_bins_count as f64 * 5.0);
        } else {
            // If no bins fit, this is a necessary evil; normalize the cost.
            score = 25.0;
        }
    }

    // 5. Mean Residual Alignment: Favor bins that keep the overall mean_residual stable.
    // If post_residual is far from the current mean, penalize slightly to keep bin states uniform.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Start with the post_residual as the base penalty for unused space.
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to encourage tight packing.
    // If post_residual is 0, we have a perfect fit.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // prioritize this bin to prepare for the next step.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + (next_item_size as f64 * 0.5);
    }

    // 3. New Bin Thresholding: Penalize opening a new bin heavily unless the 
    // current open bins are already very full.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual < 25.0 {
            score += 150.0; // Discourage opening new bins if existing ones have space
        } else {
            score += 20.0; // Neutral cost to open a new bin if existing bins are tight
        }
    }

    // 4. Fragmentation Avoidance: If the post_residual is too small to fit common items 
    // (e.g., < 10), penalize it as 'dead space' unless it is exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 5. Global Efficiency: If this is the only bin that can fit the item, 
    // incentivize taking it to prevent unnecessary new bin openings.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Progression Weighting: As we reach the end of the stream, prioritize 
    // using existing bins over new ones to reduce final bin count.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual. 
    // We want to minimize this (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalty for creating "slivers" (small, unusable gaps).
    // If post_residual is < 10, it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead logic: If the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that leave space for the next item
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // Penalize bins that "block" the next item
        }
    }

    // 3. Global state: If we are late in the stream, be more aggressive with packing (tighten constraints).
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 4. New Bin Logic: Discourage opening new bins unless necessary or significantly better.
    if is_new_bin {
        // Only open a new bin if we have many bins open or if the current options are very poor.
        if fitting_bins_count > 0 {
            score += 35.0 + (open_bins_count as f64 * 0.5);
        } else {
            score -= 5.0; // We must open a bin if no others fit
        }
    }

    // 5. Mean residual coupling: Avoid deviating too far from the average state of open bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalty for creating "dead space" (small residuals that are hard to fill later)
    // We prioritize bins that leave larger post_residuals if we are early in the stream,
    // but shift to Best-Fit behavior as the stream progresses.
    let dead_space_penalty = if post_res < 15.0 && post_res > 0.0 {
        (15.0 - post_res) * 5.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Lookahead coupling: If the next item is large, favor bins that leave enough space for it.
    // If next_item_size is 0, we treat it as a small value to avoid bias.
    let next_size = if next_item_size == 0 { 10.0 } else { next_item_size as f64 };
    let lookahead_fit = if post_res < next_size {
        (next_size - post_res) * 2.0
    } else {
        0.0
    };

    // Global bin density pressure:
    // Penalize opening new bins heavily when we have many open bins already.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (open_bins_count as f64 * 1.5) + (progress * 10.0)
    } else {
        0.0
    };

    // Non-linear coupling: 
    // We want to minimize post_residual (Best Fit) but modulate it by 
    // the distance from the mean_residual to prevent extreme bin fragmentation.
    let variance_penalty = (post_res - mean_residual).abs() * 0.5;

    let score = post_res + dead_space_penalty + lookahead_fit + new_bin_penalty + variance_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals.
    // We want to minimize post_residual (Best Fit).

    // 2. Harmonic Class Logic:
    // If post_residual is very small, it's a "tight fit" (good).
    // If post_residual is in a range that prevents the next item from fitting, penalize it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin will be unable to accept the lookahead item.
            // Penalize proportional to how much space is wasted that could have been used.
            score += 50.0 + (post_residual as f64 * 0.5);
        } else {
            // This bin can accept the next item. Reward this "synergy".
            score -= (next_item_size as f64) * 0.8;
        }
    }

    // 3. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is high enough that we don't need 
        // to force items into existing bins (which would create fragmentation).
        if mean_residual > 30.0 || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 40.0;
        }
    }

    // 4. Fragmentation Penalty:
    // If we have many open bins, penalize creating a new one unless it's a very good fit.
    if open_bins_count > (total_items / 10).max(5) {
        score += 20.0;
    }

    // 5. Harmonic refinement:
    // Favor residuals that are multiples of common item sizes (e.g., 20, 25, 50).
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the remaining space is small (1-9), it is likely unusable.
    // Penalty scales exponentially as post_residual approaches 0 from above,
    // but we heavily penalize ranges that are too small for any item (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead optimization: If the next item cannot fit in the current post_residual,
    // but could have fit if we chose a different bin, we penalize this placement.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bin pressure: If we are forced to open a new bin, only do so if the current 
    // bin_residual is exactly bin_capacity. Otherwise, penalize opening new bins.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 4. Fitting constraints: If this is the last bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean alignment: Favor bins that keep the overall mean_residual stable
    // to prevent creating extreme outliers in bin utilization.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to prioritize tight packing.
    // However, we apply a non-linear scaling to favor leaving space for future items.
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Matching: If the current post_residual can perfectly accommodate 
    // the next item, reward this placement heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
        // If it fits perfectly, reduce score further to encourage "Perfect Fit" chains.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. Mean Residual Balancing: Avoid creating bins that are significantly 
    // more empty than the current average, preventing fragmented bin states.
    let residual_diff = (post_residual as f64) - mean_residual;
    score += residual_diff.abs() * 0.5;

    // 4. Scarcity/Urgency: As we approach the end of the stream, prioritize 
    // filling bins more aggressively (less tolerance for large post_residuals).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0) * (post_residual as f64 / bin_capacity as f64);

    // 5. New Bin Thresholding: If this is an empty bin (new bin candidate), 
    // penalize opening it unless the existing fitting bins result in poor fits.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average fit is already very poor
        score += 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If this is the last fitting bin, give it a slight priority boost 
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
