        score += 50.0;
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if current open bins are poor.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -100.0; // Must open first bin
        } else {
            // Only open a new bin if the mean residual of current bins is already quite low
            // or if we have no good fits for the current item.
            score += 40.0 + (mean_residual * 0.5);
            if fitting_bins_count == 0 {
                score -= 60.0;
            }
        }
    }

    // 4. Pressure Management:
    // As the stream progresses, prioritize closing bins to reduce the number of active bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmented space too small for most items)
    // We penalize post_residual values in the 1-9 range heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is too small for the next item, add a penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - progress);
    }

    // Global state: if we have many bins open, try to pack tighter (Best Fit)
    // If we have few bins, we are more lenient.
    score += (open_bins_count as f64) * 0.5;

    // Dynamic threshold: If this is the only bin that fits, prioritize it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New bin logic:
    // Only open a new bin if the current fit is extremely poor (large post_residual)
    // or if we are early in the process and don't want to fragment bins.
    if bin_residual == bin_capacity {
        // High cost to open a new bin unless the average residual is already high
        score += 65.0 - (mean_residual * 0.5);
    }

    // Final adjustment based on mean residual to avoid outlier bins
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
