    // Global state awareness: penalize creating bins that deviate significantly 
    // from the current mean residual to promote uniform bin filling.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * 0.8;

    // Criticality adjustment: if this is the only bin that fits, 
    // heavily incentivize using it to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
