        score += (open_bins_count as f64) * 15.0;
    }

    // 3. Lookahead Optimization:
    // If we have a next item, check if the current post_residual can accommodate it.
    // If the next item fits perfectly or well in the remaining space, lower the score.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that leave exactly enough space for the next item.
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.2;
        } else {
            // If it doesn't fit, penalize based on how much space is wasted.
            score += 5.0;
        }
    }

    // 4. Mean Residual Balancing:
    // Avoid bins that deviate significantly from the current mean efficiency.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Last Chance Logic:
    // If this is the only bin that can fit the item, prioritize it to avoid an unnecessary new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
