        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Lookahead logic: If the next item is large, favor bins that leave enough space for it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty if this placement prevents the next item from fitting here
            score += 20.0;
        } else {
            // Bonus if this placement allows the next item to fit perfectly
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 15.0;
            }
        }
    }

    // Constraint: Avoid opening a new bin unless necessary
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can fit the item
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Necessary to open a new bin
            score = 0.0;
        }
    } else {
        // If it's an existing bin, apply a slight bias towards filling the emptiest bins first
        // to consolidate space (Best-Fit behavior)
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalty for creating a bin that is too empty to be useful for the next item
    // but too full to fit many future items.
