        (next_item_size as f64 - post) * 2.5
    } else {
        0.0
    };

    // Reward bins that maintain a residual close to the mean_residual of all bins,
    // encouraging uniformity and reducing the variance of bin utilization.
    let uniformity_bonus = (post - mean_residual).abs() * 0.5;

    // Encourage creating a new bin (bin_residual == bin_capacity) only when
    // fitting the item into existing bins would leave a very small, unusable gap.
    // As progress increases, we become more conservative about opening new bins.
    let new_bin_bias = if bin_residual == bin_capacity {
        (1.0 - progress) * 15.0 + (fitting_bins_count as f64 * 5.0)
    } else {
        0.0
    };

    // Non-linear coupling: Prefer post_residuals that are either very small (tight fit)
    // or large enough to accommodate the next item.
    let residual_sq = post * post * 0.01;

    let mut score = post + residual_sq + next_fit_penalty + uniformity_bonus + new_bin_bias;

    // Favor bins that are already open to keep the number of active bins low.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64 * 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
