    // 1. Best-Fit Penalty: Penalize large empty spaces to keep bins tight.
    // 2. Lookahead Logic: If post_residual can fit the next item, reward this bin significantly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Further reward if the post-fit residual is very small (near perfect pack).
        score -= (100.0 - (post_residual - next_item_size) as f64) * 0.2;
    }

    // 3. Last Chance Heuristic: If this is the only bin that can fit, prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // 4. Global State Awareness: If we are near the end of the stream, 
    // be more aggressive about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // 5. New Bin Penalty: Heavily penalize opening a new bin unless the fit is perfect.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // New bin is acceptable if it can start a good pair.
            score += 20.0;
        } else {
            // Otherwise, strongly discourage opening a new bin.
            score += 45.0;
        }
    }

    // 6. Mean Residual Balancing: Avoid creating bins that are significantly 
    // worse than the average existing bin.
    if post_residual as f64 > mean_residual && open_bins_count > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post-residuals (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (fragmentation)
    // If post_residual is small but not zero, it's often hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0; // Penalize bins that block the next item
        }
    }

    // Global state awareness:
    // If we have many open bins, we should be more aggressive about filling existing ones
    // rather than opening new ones.
    if is_new_bin {
        if open_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing capacity
            score += 40.0 + (mean_residual * 0.5);
        }
        // As the stream nears the end, opening a new bin is increasingly costly
        score += progress * 50.0;
    } else {
        // If this is the last bin that can fit the item, prioritize it
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Encourage balanced filling (keeping residuals near the mean)
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bins heavily early on, but allow them as the stream nears completion
    // to avoid trapped small residual space.
    let mut score = post_residual as f64;

    if is_new_bin {
        // Base penalty for opening a new bin is the capacity itself
        score = bin_capacity as f64 * 1.5;
        // As we progress, the cost of opening a new bin decreases relative to the risk
        // of leaving behind fragmented space that cannot fit future items.
        score -= progress * 40.0;
    } else {
        // Best-Fit Decreasing logic: prioritize bins where the post_residual is minimal.
        // We add a penalty if the remaining space is too small to fit any likely future item.
        // If post_residual is small but > 0, it's often "dead space".
        if post_residual > 0 && post_residual < 10 {
            score += 15.0 * (1.0 - progress);
        }

        // If this bin is the last chance for this item, prioritize it to save open bins.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Lookahead: If next_item_size is large, favor bins that leave enough room for it.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Smooth coupling: use mean_residual to penalize bins that deviate from the average packing density.
    let density_penalty = (post_residual as f64 - mean_residual).abs() * 0.5;
    score += density_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // We want to minimize post_residual, so it stays as the base score.

    // 2. Lookahead optimization: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin because it creates 
    // a "stranded" space that can't fit the next expected item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that leave exactly enough space for the next item (synergy)
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 3. Harmonic class alignment:
    // Items often fit well into fractions of the capacity (e.g., 100/2, 100/3, 100/4).
    // Penalize residuals that fall into "awkward" prime-like zones.
    let residual_mod = post_residual % 25;
    score += residual_mod as f64 * 0.1;

    // 4. Thresholding: Avoid opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the number of currently fitting bins is very low.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if we have existing capacity
            score += 45.0 + (open_bins_count as f64 * 0.5);
        } else {
            // If no bins fit, new bin is mandatory; set to a baseline
            score = 10.0;
        }
    } else {
        // Encourage filling existing bins that are already "near empty" to consolidate
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // 5. Progress scaling: As we approach the end of the stream, be more aggressive
    // about using up existing bin space to avoid trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that create unusable slivers (1..9).
    // These are too small for almost any item, increasing the likelihood of stranded space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can accommodate the item.
            score += 100.0 + (open_bins_count as f64 * 5.0);
        } else {
            // If no other bin fits, this is mandatory.
            score = 0.0;
        }
    } else {
        // 4. Efficiency Bias: Favor bins where the post_residual is closer to the mean_residual
        // of open bins to keep the pack density uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // 5. Last Chance Heuristic: If this is the only bin that fits, prioritize it heavily
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // 6. Progression scaling: As we approach the end of the stream, be more aggressive
    // about filling gaps (reduce penalty for small residuals).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
