        } else if post_residual > next_item_size {
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Cannot fit next item, penalize proportionally to the wasted space
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // 3. Fragmentation Control: Avoid creating bins with residual space below 10 (unusable).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // 4. Mean Residual Balancing: Favor bins that stay near the global average to prevent outliers.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy cost unless 
    // it's the only option or the current state is highly fragmented.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // Essential, must open
        } else {
            // Heavy penalty for opening a new bin if existing ones can fit the item
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 6. Progression scaling: As we approach the end of the stream, be more conservative.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Heuristic Strategy: Best Fit Decreasing (BFD) logic enhanced with lookahead and pressure management.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize empty bins unless we are forced to or the current fit is extremely inefficient.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty for opening a new bin if there are existing options.
            // This threshold tightens as we progress through the stream.
            score += 100.0 + (50.0 * progress);
        } else {
            // No options, this is the forced base cost.
            score = 0.0;
        }
    } else {
        // 2. Lookahead logic: If the next item fits into the current post_residual, 
        // prioritize this bin to preserve the packing density.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }

        // 3. Global state pressure: If open_bins_count is high, prioritize smaller post_residuals
        // to consolidate space. If open_bins_count is low, we can afford slightly larger gaps.
        let pressure = (open_bins_count as f64) / 10.0;
        score += post_residual as f64 * (0.1 + (pressure * 0.05));

        // 4. Tightness bias: Reward placements that leave a residual close to the mean_residual
        // to keep bin states uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Final constraint: If this is the last fitting bin, strongly prefer it to avoid 
    // fragmenting new space.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating a "fragmented" bin (residual too small to fit common items).
    // If post_residual is < 10, it's likely dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - progress.powi(2));
    }

    // Lookahead logic: if the next item is large, avoid small post_residuals.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Dynamic preference: Early stage, pack tightly; late stage, prioritize closing bins.
    // We penalize opening new bins heavily early on.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalty is high early, decreases as we reach the end of the stream.
        score += 40.0 * (1.0 - progress);

        // If we have very few open bins, opening a new one is more expensive.
        score += (1.0 / (open_bins_count as f64 + 1.0)) * 20.0;
    } else {
        // Reward bins that have residuals close to the mean, promoting balanced occupancy.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.1;
    }

    // If this is the last chance to fit the item in an existing bin, reduce penalty.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large residuals after placement.
    // The base score starts at post_residual; we refine this based on packing density.

    // 2. Harmonic Class Logic:
    // We prioritize keeping the post_residual as a multiple of common item sizes (e.g., 20, 25, 50).
    // This reduces fragmentation by leaving "useful" gaps for future items.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 3. Lookahead Integration:
    // If we have a lookahead item, we penalize bins that cannot fit it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0; // Significant penalty for blocking the next item
        } else {
            // Reward bins that leave exactly enough space for the next item
            let fit_slack = (post_residual - next_item_size) as f64;
            score -= fit_slack * 0.2;
        }
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), it is only desirable 
    // if the existing open bins are all "poor" fits (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless necessary.
        // We scale this penalty by the number of open bins to encourage consolidation.
        score += 35.0 + (open_bins_count as f64 * 2.0);
    } else {
        // If it's an existing bin, reward it if it's the last chance (fitting_bins_count == 1)
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 5. Density Balancing:
    // Penalize bins that deviate significantly from the mean_residual of current bins.
    // This encourages a uniform fill rate across all active bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 6. Progress Scaling:
    // As we approach the end of the stream, prioritize closing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the "unusable" range (1-9), 
    // it is highly likely to become wasted space. Heavily penalize this.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bin Pressure: Penalize opening a new bin if we have many active bins,
    // but reward it if the current fit is extremely poor (Best Fit Decreasing logic).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current mean residual is already quite high
        // or if we have very few bins open (to prevent fragmentation).
        score += (open_bins_count as f64 * 2.5) - (mean_residual * 0.5);
    } else {
        // Reward placements that leave the bin residual close to the average of others
        // to encourage consistent bin utilization.
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    // 3. Lookahead Sensitivity: If the next item is large, avoid creating 
    // a post_residual that is too small to accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual >= 10 {
            // This bin will be unusable for the next large item. Penalize moderately.
            score += 15.0;
        }
    }

    // 4. Scarcity Penalty: If this is the last bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize leaving small gaps that are hard to fill (the "fragmentation" trap).
    // Gaps between 1 and 9 are statistically likely to remain unused in a 10-80 distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the post-residual, heavily favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.8;
    }

    // 3. Adaptive Thresholding: If we are near the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. Bin Consolidation: If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. New Bin Penalty: If this is a new bin, heavily penalize it unless it's the only option.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many open bins, penalize opening a new one even more to force consolidation.
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Mean Residual Balancing: Avoid bins that are significantly emptier than the average.
    if (bin_residual as f64) > mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
