pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (lower post_residual is better)
    // We add a penalty for opening a new bin specifically when fitting_bins_count > 0.
    let mut score = post * post;

    // Penalty for leaving "dead space" (small residuals that are unlikely to fit future items).
    // If post_residual is small (e.g., < 10), it's often a waste.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post).powi(3);
    }

    // Lookahead logic: if next_item_size is large, favor larger post_residual to accommodate it.
    // Otherwise, favor filling bins tightly.
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        score += diff.powf(1.5) * (1.0 - progress);
    }

    // Dynamic thresholding: as the stream nears the end, become more aggressive at packing
    // to avoid leaving too many partially filled bins.
    if fitting_bins_count == 0 {
        // This is a new bin candidate
        score += 50.0 * (1.0 + progress);
    } else {
        // Existing bin candidate: apply a slight bonus to bins that are already well-filled
        // based on the mean_residual of open bins.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.5;
    }

    // Penalize high open_bins_count to encourage consolidation
    score += (open_bins_count as f64).powf(1.2) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
