    // 2. Lookahead optimization: If the next item fits into the post_residual, 
    // reward this placement to keep bins tightly packed.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Harmonic class awareness: 
    // If we are at a point where the residual is a factor of capacity, preserve it.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Penalty for opening a new bin if we have existing capacity.
        score += 25.0;
    }

    // 4. Fitting constraints:
    // If this is the only bin that can fit the item, we must prioritize it 
    // to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. Mean residual balancing:
    // Avoid creating bins that are significantly emptier than the current average.
    if post_residual as f64 > mean_residual + 20.0 {
