    // 6. Progression scaling:
    // As we approach the end of the stream, prioritize closing bins 
    // (low post_residual) over keeping them open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

