    // to force better packing into existing ones.
    let progress = step_index as f64 / total_items as f64;
    let bin_pressure = (open_bins_count as f64) * (1.0 + progress);

    // 4. Handle New Bin Candidate
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy barrier cost
