    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space" that is too small for most items.
    // As the stream progresses, we become more conservative about creating small gaps.
    if post < 20.0 && post > 0.0 {
        score += (20.0 - post) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= (next_item_size as f64) * 0.5;
        } else {
            score += (next_item_size as f64 - post) * 0.8;
        }
    }

    // Encourage filling bins that are already "below average" in residual to tighten packing.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    // If this is the only bin that fits the item, heavily prioritize it to avoid 
    // unnecessary new bins unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New bin threshold: only open a new bin if the best existing fit is extremely poor 
    // (post_residual very close to bin_capacity, implying a very large gap left).
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (small residuals that are hard to fill)
    // We penalize residuals that are too small to fit the average incoming item size.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // 2. Harmonic Lookahead: If the next item fits perfectly into the post_residual,
    // we heavily favor this bin to maintain high density.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Pressure management: If we are near the end of the stream, 
    // we prioritize filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many open bins already,
        // unless we are at the very beginning of the stream.
        score += (open_bins_count as f64 * 15.0) * (1.0 - progress);
        score += 20.0; // Base cost of opening a bin
    } else {
        // Reward packing into existing bins based on how much they deviate from the mean.
        // This encourages "leveling" bin usage.
        score -= (bin_residual as f64 - mean_residual).abs() * 0.1;
    }

    // 4. Critical threshold: If this is the last bin that fits the item,
    // reduce score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Harmonic Class Logic: Penalize post_residuals that are multiples of 
    // common small item sizes (e.g., 10, 20) as they are "versatile" 
    // and should be saved for harder-to-fit items.
    if post_residual > 0 && post_residual % 10 == 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": gaps smaller than the smallest possible item (10)
    // are highly undesirable as they cannot accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if the next item cannot fit into the current post_residual,
    // we penalize this placement to keep the bin open for a better fit.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Pressure normalization: penalize opening new bins when many are already open,
    // but reward opening a new bin if the current fit is extremely poor (Best Fit Decreasing logic).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only consider a new bin if the mean_residual is already quite low,
        // otherwise, force usage of existing bins to keep packing density high.
        score += (open_bins_count as f64 * 2.5) + (mean_residual * 0.5);
    } else {
        // Reward bins that are becoming "full" (low post_residual) to consolidate space.
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Critical thresholding: If this is the only bin that can fit the item,
    // reduce the penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Aggressive 2-step lookahead matching
    // Base score is the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin unless the current filling strategy is inefficient.
    // If we have open bins, prioritize them over creating new ones.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0;
    }

    // 2. Lookahead optimization: If the post_residual can perfectly or nearly perfectly
    // accommodate the next item, we reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact fits for the next item
            let gap = (post_residual - next_item_size) as f64;
            score -= (50.0 - gap).max(0.0);
        } else {
            // If the next item won't fit, penalize creating small, unusable gaps (fragmentation)
            if post_residual > 0 && post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // 3. Pressure management: As the stream progresses, tighten tolerance for empty space.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress;

    // 4. If this is the last bin that can fit the item, consider it a high-priority 
    // candidate to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Penalize bins that deviate significantly from the mean residual to maintain
    // uniform packing density across the bin set.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // We prioritize bins that result in a "tight" fit (low post_residual),
    // but penalize creating "dead space" that cannot accommodate the next_item_size.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin:
    // Only open a new bin if the current fit is very poor (large residual) 
    // or if we are forced to.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist, 
            // unless the current item is very large.
            score += 40.0 + (item_size as f64 * 0.5);
        } else {
            // No other options, this is the baseline.
            score = 25.0; 
        }
    }

    // 2. Lookahead optimization:
    // If next_item_size exists, penalize bins that leave a post_residual 
    // smaller than the next item, effectively wasting that space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;

        // If the current bin becomes "unusable" for the next item, 
        // weigh it against the global mean_residual.
        if post_residual < 15 {
            score += 10.0 * (1.0 - progress);
        }
    }

    // 3. Global state balance:
    // Avoid creating too many open bins if we are late in the stream.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * progress * 2.0;
    }

    // 4. Tightness reward:
    // Strongly prefer bins that result in a near-perfect fit (residual < 5).
    if post_residual < 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res_f = post_residual as f64;

    // Base heuristic: Best Fit (minimize post_residual).
    // We want to keep post_residual small to pack tightly.
    let mut score = post_res_f;

    // Penalty for creating "dead space": if post_residual is small but not zero,
    // it often renders the bin useless for future large items.
    // We penalize very small residuals (1-9) that are likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - (post_res_f / 10.0));
    }

    // Lookahead coupling: If a next item exists, penalize bins that cannot fit it
    // if this bin currently has the capacity to hold it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can accommodate the next item
        } else {
            score += 5.0 * (1.0 - progress); // Penalize blocking the next item
        }
    }

    // Adaptivity: As the stream progresses, prioritize closing bins (lower mean_residual)
    // to avoid fragmentation.
    score += (mean_residual * progress) * 0.5;

    // Boundary condition: If this is the only bin that fits, prioritize it heavily
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New Bin Logic: If the bin is brand new (bin_residual == bin_capacity),
    // only choose it if the current best fit is poor.
    if bin_residual == bin_capacity {
        // High cost to open a new bin, but scale it down as we reach the end
        // of the stream to ensure we don't leave items stranded.
        score += 45.0 * (1.0 - progress * 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (minimize post_residual)
    // We penalize larger post_residuals to keep bins tight.

    // 2. Harmonic Class Logic:
    // If we have a next item, we want to see if the current placement leaves a residual
    // that is "harmonic" to the next item (e.g., leaving exactly enough space for it).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward placements that leave exactly enough room for the next item (perfect fit)
            if post_residual == next_item_size {
                score -= 45.0;
            }
            // Penalize leaving a sliver that is too small for the next item but wastes space
            if post_residual < next_item_size && post_residual > 0 {
                score += 20.0;
            }
        }
    }

    // 3. New Bin Thresholding:
    // If the bin is new (residual == capacity), we only want to pick it if existing bins are "poor"
    // or if the current item is very large (e.g., > 70% of capacity).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if we have fitting options
            score += 65.0;
        }
        // If the item is large, reduce the penalty to encourage new bin usage for large items
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // 4. Mean Residual Balancing:
    // Try to avoid opening new bins if the average residual of current bins is already high.
    if bin_residual == bin_capacity && mean_residual > 30.0 {
        score += 30.0;
    }

    // 5. Modulo-based "Dead Space" Penalty:
    // Penalize residuals that are likely to be unusable (e.g., < 10) unless the item fits perfectly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 6. Final progression adjustment: 
    // Towards the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (gaps smaller than the smallest likely item size 10)
    // If post_residual is in [1, 9], it's highly likely to be unusable.
    if post_residual > 0 && post_residual < 10 {
