    // If next_item_size is large, we prefer larger post_residual to accommodate it
    let lookahead_penalty = if next_item_size > 0 {
        if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 0.5
        } else {
            0.0
        }
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), calculate its cost
    // We only open a new bin if the existing fits are objectively terrible
    let final_score = if bin_residual == bin_capacity {
        // New bin cost is high, but decreases as we exhaust options or as the stream progresses
        (bin_capacity as f64 * 0.6) - (progress * 10.0) + (open_bins_count as f64 * 0.5)
    } else {
        score + lookahead_penalty
    };

    final_score
}

