            score += 10.0;
        }
    }

    // 3. Fragmentation control:
    // Avoid creating very small residuals (e.g., < 10) unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Density optimization:
    // Favor bins that stay closer to the global mean residual to keep packing uniform.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 5. Urgency:
    // If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progress scaling:
    // As we approach the end of the stream, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

