    }

    // 4. Global state adjustment: If current bin residual is far from the mean,
    // we want to balance the bins to keep them uniform, or cluster to clear bins.
    // Penalize creating "fragmented" bins that are far from the mean capacity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. Critical thresholding: If this is the last chance to fit the item in an existing bin,
    // lower the score to force the fit rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Dynamic horizon: As the stream nears the end, become more conservative about
    // opening new bins.
    if progress > 0.8 {
        score += (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin heavily early on, but allow it if it's the only option.
    // As the stream progresses, allow more bin creation if residuals are poor.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Calculate fit quality: prioritize bins that leave very little space (Best Fit)
    // but penalize creating "dead space" (e.g., leaving 1-5 units is often worse than 0).
    let dead_space_penalty = if post > 0.0 && post < 8.0 {
        15.0 - (post * 1.5)
    } else {
        post * 0.1
    };

    // Lookahead coupling: if the next item is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next_item_size, it's a "bad" fit.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 0.8
    } else {
        0.0
    };

    // Interaction with mean_residual: favor bins that keep the overall average residual low.
    let mean_residual_bias = (post - mean_residual).abs() * 0.2;

    // Final score: lower is better.
    // Combine base residual, dead space, lookahead, and progress-based bin opening.
    let score = dead_space_penalty + lookahead_penalty + mean_residual_bias + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
