    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation)
    // We penalize small residuals that are likely to remain unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if we know the next item, prioritize bins that can fit it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that keep capacity for the next item
        } else {
            score += 10.0; // Penalize bins that would block the next item
        }
    }

    // Dynamic thresholding based on stream progress
    // As the stream nears the end, we become more conservative about opening new bins
    if is_new_bin {
        // Higher cost to open a new bin as we progress (to pack tighter)
        score += 40.0 + (30.0 * progress);

        // If other bins can fit the item, heavily penalize opening a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Encourage using existing bins that are closer to the mean residual to keep them balanced
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += 0.5 * residual_diff;
    }

    // Interaction term: combine density with progress
    // Reward bins that become very full as we reach the end of the stream
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= (fill_ratio * 10.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

