    // This reduces fragmentation by aligning bin space with potential future items.
    if post_residual > 0 {
        let harmonic_alignment = (post_residual % 10) as f64;
        score += harmonic_alignment * 2.0;
    }

    // 3. Lookahead Integration: If next item fits in the current post_residual, reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
