        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 6. Global Trend: As the stream nears completion, become more aggressive with packing
    // to minimize the number of trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
