pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize mid-range gaps 
    // that are too small for most items (10-30).
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 55.0;
        // Further reward if it nearly fills the bin
        if post_residual - next_item_size < 10 {
            score -= 20.0;
        }
    }

    // 3. Global State Awareness: If we are running out of items, prioritize filling 
    // existing bins over opening new ones.
    if progress > 0.85 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Scarcity Logic: If this is the only bin that can fit the item, 
    // check if it's a "wasteful" fit.
    if fitting_bins_count == 1 && post_residual > 50 {
        score += 30.0; 
    }

    // 5. New Bin Threshold: If this is a new bin (residual == capacity), 
    // apply a high cost to force the algorithm to prefer filling existing bins 
    // unless the fit is extremely poor everywhere else.
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    }

    // 6. Dynamic Pressure: As the stream progresses, increase the penalty for 
    // leaving large residuals in bins to encourage tighter packing.
    score += (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow flexibility as the stream ends.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (50.0 * (1.0 - progress)).powf(1.5) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Best Fit Decreasing logic: reward smaller post_residual (tighter packing).
    // Use non-linear scaling to prefer filling bins to near-zero capacity.
    let mut score = post.powf(1.8);

    // Lookahead coupling: If the next item is large, avoid leaving small slivers.
    // If post_residual is smaller than the next item, it creates "dead space".
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post) * 5.0;
        }
    }

    // Encourage density by penalizing bins that deviate from the current mean residual.
    // This helps keep bins balanced in their remaining capacity.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    // Last chance logic: If this is the only bin that fits, reward it to prevent 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals too small to fit common items)
    // Residuals < 10 are generally unusable given the item range (10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Harmonic Class Logic: Reward bins that align with the next item
    // If the next item can fit in the post_residual, drastically lower the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if the post-post residual is near zero (perfect packing)
        let second_post = post_residual - next_item_size;
        if second_post < 5 {
            score -= 20.0;
        }
    }

    // 3. Pressure management: If this is the only bin that can fit the item, 
    // it is highly valuable; otherwise, penalize bins that deviate from the mean.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // 4. Global distribution awareness: 
    // As the stream progresses, favor tighter packing to prevent bin fragmentation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (bin_residual as f64 - mean_residual).abs();

    // 5. New Bin Logic:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Penalize this unless the open bins are already very full (mean_residual is low).
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit future items.
    // If post_residual is in (0, 10), it is likely "dead space" as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Integration: If the next item cannot fit in this post_residual,
    // we penalize the current placement unless it's a perfect fit.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if we have options, 
    // but reward filling bins tightly when many are open.
    if bin_residual == bin_capacity {
        // New bin penalty: only open if we have no good fits elsewhere.
        score += 40.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward packing into existing bins, especially those with smaller residuals.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Scarcity Adjustment: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, 
    // prioritize closing bins (minimizing residuals) over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Base score is the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalty for creating "slivers" (unusable space < 10).
    // If post_residual is small but > 0, it is likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization:
    // If we have a next item, we want to prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin is a great candidate for the next item.
            score -= 30.0;
        } else {
            // This bin will not fit the next item; penalize if there are other bins that might.
            score += 10.0;
        }
    }

    // 3. Global state adaptation:
    // If we have many open bins, be more aggressive at packing tightly (penalize new bins).
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we have very few open bins or very few items left.
        score += 45.0 + (open_bins_count as f64 * 2.0);

        // If we are near the end of the stream, prioritize closing out.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 20.0;
    }

    // 4. Mean residual alignment:
    // Avoid creating bins that are significantly "emptier" than the current average.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    }

    // 5. Urgency:
    // If this is the ONLY bin that can fit the item, we must take it (strong reward).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (small gaps are harder to fill)
    // We prioritize bins where the post_residual is as small as possible (Best Fit).
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If the next item fits into the remaining space, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the fit is extremely poor.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, but scale it down as we approach the end of the stream.
        score += 150.0 * (1.0 - progress);
    }

    // 4. Fragmentation Avoidance: If this bin is the last one that can fit the item,
    // take it to avoid creating a new bin later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global State Balancing: Avoid creating bins that are significantly emptier than the average.
    // If the new residual is significantly higher than the mean, penalize it to pack tighter.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 6. Tightness Bonus: Reward bins that are nearly full (e.g., < 10 remaining).
    if post_residual < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual, which we want to minimize (Best-Fit approach)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: scales with progress to discourage early waste
    // and increases as the number of open bins grows.
    if is_new_bin {
        score += (bin_capacity as f64 * 0.4) + (open_bins_count as f64 * 5.0 * (1.0 - progress));
    } else {
        // Reward bins that are "tight" fits, but penalize creating "dead zones" (< 10 units)
        // that are unlikely to be filled by future items.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0 * (1.0 - progress);
        }

        // Lookahead coupling: if the next item fits in the current post_residual,
        // prioritize this bin heavily to avoid fragmentation.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64 * 0.8);
        }

        // Coupling with global state: if this bin's residual is significantly better 
        // than the current average, prioritize it.
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

    // Adjust for scarcity: if this is the only bin that fits the item, 
    // it becomes much more attractive to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize "wastage potential" by balancing Best-Fit with a lookahead-aware harmonic penalty.
    // We prioritize bins that leave a residual which is either 0 (perfect fit) or large enough to accommodate
    // the next item, while penalizing residuals that are "dead zones" (e.g., < 10).

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (too small to fit most items, assuming distribution starts at 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: If the next item can fit in the post_residual, strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
