    }

    // 3. Pressure management: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 4. New bin aversion: Heavily penalize opening a new bin unless the current mean residual is very low.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 60.0;
        } else {
            score += 30.0;
        }
    }

    // 5. Fill-Density scaling: Reward bins that become "tight" (residual < 15) to minimize total bin count.
    if post_residual < 15 {
        score -= 15.0;
    }

    // 6. Distribution adaptation: As the stream progresses, favor tighter packing to avoid stranded items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
