pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // Minimizing post_residual is the baseline (Best Fit).

    // 2. Lookahead Matching (The "Tightness" Bonus):
    // If post_residual is close to the next_item_size, we favor this bin to enable a future perfect fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward placements that leave exactly enough room for the next item
        score -= 50.0 * (1.0 / (1.0 + diff));
    }

    // 3. Mean Residual Balancing:
    // Avoid creating bins that are significantly "tighter" than the current average of open bins,
    // which helps keep future flexibility balanced across the open set.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * residual_deviation;

    // 4. New Bin Thresholding:
    // If the bin is brand new (residual == capacity), apply a heavy cost based on the number of open bins.
    // This discourages opening new bins unless the fit in existing bins is extremely poor.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Last Chance Logic:
    // If this is the only bin that can fit the item, we lower the cost to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progression Scaling:
    // As we approach the end of the stream, prioritize packing density over future-proofing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost: The post_residual represents the wasted space if no further items fit.
    let mut score = post_residual as f64;

    // 2. Lookahead optimization: If next_item_size is known, penalize bins that leave 
    // too little space for the upcoming item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize hard if we block the next item from this bin
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else {
            // Reward if the bin is a perfect fit for the next item
            if post_residual == next_item_size {
                score -= 15.0;
            }
        }
    }

    // 3. Global state: Avoid opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), add a significant penalty
    // unless it's the only option or the current average residual is very poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the average residual is already quite low (highly fragmented)
            // or if we are nearing the end of the stream.
            let progress = step_index as f64 / total_items as f64;
            score += 45.0 + (mean_residual * 0.5) + (progress * 10.0);
        }
    } else {
        // 4. Fill-priority: Reward bins that become "tight" (highly filled).
        // This encourages Best-Fit behavior.
        score -= (bin_capacity - post_residual) as f64 * 0.2;

        // 5. Criticality: If this is the last fitting bin, prioritize it to save open bin slots.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 6. Stability adjustment: penalize high open bin counts to encourage consolidation.
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
