pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // The core strategy is Best-Fit Decreasing logic (minimizing post_residual) 
    // modified by lookahead and global state awareness.

    let mut score = post_residual as f64;

    // 1. Penalize opening new bins unless absolutely necessary (or if the fit is terrible).
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, 
    // we strongly favor this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Further reward if it perfectly fills the bin
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. Avoid leaving "dead space" that is too small for any likely future item.
    // Given items are 1-100, leaving < 10 is usually inefficient.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Balance the load: Penalize bins that deviate too far from the mean residual.
    // This helps keep bins balanced, preventing a single bin from becoming a "sink" 
    // for only tiny items.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Urgency factor: If this is the only bin that fits the item (fitting_bins_count == 1),
    // we should prioritize placing it here to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Progress scaling: As the stream nears completion, tighten the constraints
    // to force tighter packing (reduce total bins).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic Strategy: Best-Fit Decreasing variant with lookahead-aware capacity preservation.
    // We aim to minimize post_residual (Best Fit), but penalize creating "fragmented" gaps 
    // that are too small for the next expected item or the global average.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for leaving space smaller than the next item if possible
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
