    }

    // 4. Global state coupling: 
    // If the mean residual of current bins is high, we prefer to fill existing bins 
    // to consolidate space, penalizing the use of empty bins further.
    if mean_residual > 30.0 {
        score += (mean_residual - 30.0) * 0.5;
    }

    // 5. Exponential penalty for creating "dead space" (very small residuals that are unlikely to fit future items)
    // Residuals between 1 and 9 are statistically poor for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 / (post_residual as f64 + 0.1);
    }

