}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation exponentially as the stream progresses
    let new_bin_penalty = if is_new_bin {
        25.0 + (progress * 75.0).powf(1.5)
    } else {
        0.0
    };

    // Calculate "tightness" score: prefer post_residuals that are either 0 (perfect fit)
    // or large enough to accommodate the next item.
    // We use a non-linear penalty for residuals that are small but not zero ("dead space").
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Lookahead logic: if the next item is large, prioritize bins that can accommodate it.
    let next_item_fit_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -10.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Global optimization: discourage opening many bins early, but encourage packing density
    // as the stream nears the end to finish off existing bins.
    let efficiency_bias = (post_residual as f64) * (0.5 + 0.5 * progress);

    // Penalize bins that deviate significantly from the mean residual to keep distribution uniform
    let uniformity_penalty = (post_residual as f64 - mean_residual).abs() * 0.1;

    let score = (post_residual as f64) 
        + new_bin_penalty 
        + dead_space_penalty 
        + next_item_fit_bonus 
        + efficiency_bias 
        + uniformity_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
