    // If we are late in the stream, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to how many bins are already open.
        // As progress increases, we become more desperate to fit in existing bins.
        score += (open_bins_count as f64 * 2.0) + (progress * 50.0);
    }

    // 5. Fitting constraints:
    // If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Mean residual balancing:
    // Avoid creating bins that are significantly emptier than the average.
    if (bin_residual - item_size) as f64 > mean_residual {
