    // Lookahead logic: if the next item is large, favor bins that have enough space for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: as we reach the end of the stream, prioritize tighter packing
    // more aggressively to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize the "New Bin" option heavily early on, but allow it to be chosen 
    // if the post_residual of existing bins is extremely poor (creating dead space).
    if bin_residual == bin_capacity {
        score += 45.0 + (20.0 * progress);
    }

    // Coupling: If the mean residual of existing bins is high, we are under-utilizing
    // the current set; penalize opening new bins even more.
    score += (mean_residual / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
