    // If this is a new bin, penalize based on how many bins are currently open.
    // If open_bins_count is low, we are more willing to open a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 15.0) + (100.0 * (1.0 - (step_index as f64 / total_items as f64)));
    }

    // 2. Lookahead optimization:
    // If the next item is large, we want to prioritize leaving space for it.
    // If the next item fits in the current post_residual, we reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            // If next item does NOT fit, penalize if we have other options.
            score += (next_item_size as f64) * 0.5;
        }
    }

    // 3. Global state balancing:
    // Avoid creating too many bins with very small residuals (unusable space).
    // If the post_residual is very small (e.g., < 5), it's often better to avoid 
    // unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 8 {
        score += 20.0;
    }

    // 4. Pressure handling:
    // If we are late in the stream, prioritize closing bins (lower residual).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (bin_residual as f64 * 0.1);

    // 5. Fitting constraint:
    // If this is the only bin that fits, we should prioritize it significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
