    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // 2. Lookahead Coupling: Reward placements where post_residual fits the next item perfectly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward if post_residual can accommodate the next item (synergy)
            score -= (next_item_size as f64) * 1.5;
            // Strong reward for near-perfect fit for the next item
            if post_residual < (next_item_size + 5) {
                score -= 20.0;
            }
        } else {
            // Penalize if the current placement prevents the next item from fitting here
            score += (next_item_size as f64) * 0.8;
        }
    }

    // 3. New Bin Thresholding: If this is an empty bin, penalize it unless no other bin fits well
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin
        score += 45.0;
        // Reduce penalty if current item is very large (hard to pack)
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // 4. Mean Residual Balancing: Prefer bins closer to the global average residual
    // This prevents fragmentation by keeping bin fill-levels clustered
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Urgency weighting: If only one bin fits, prioritize it heavily to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progressive packing: As the stream nears the end, prioritize filling existing bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: discourage unless existing bins are extremely fragmented
        score = 25.0 + (mean_residual * 0.5) + (progress * 15.0);
    } else {
        // Best-fit base: lower post_residual is good.
        // Penalty if this bin was the "last chance" (fitting_bins_count == 1) 
        // but it leaves behind a "dead zone" (e.g., 1-9 residual).
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }

        // Lookahead heuristic: If the next item can fit in the post_residual, 
        // reward this placement heavily.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }

        // Global state correction: if we have many open bins, penalize larger residuals
        // to force tighter packing as the stream progresses.
        if open_bins_count > 5 {
            score += (post_residual as f64) * 0.2;
        }

        // Favor bins that align with the global mean to reduce variance in bin usage.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual).
    // We add a penalty for creating small, unusable gaps (1..9).
    let mut score = post;
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if we have a next item, penalize leaving a residual that
    // is smaller than the next item if possible.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post > 0.0 && post < next {
            score += 40.0 * (1.0 - (post / next));
        }
    }

    // Dynamic pressure: as the stream progresses, tighten the tolerance for opening new bins.
    // We increase the cost of opening new bins (bin_residual == bin_capacity) as progress increases.
    if bin_residual == bin_capacity {
        // Base cost for a new bin is high, scaled by progress and current open bin efficiency.
        let new_bin_cost = 35.0 + (progress * 30.0) + (mean_residual * 0.5);
        score += new_bin_cost;
    } else {
        // Reward bins that have high utilization (low residual) to keep them packed.
        // This acts as a counter-pressure to the new_bin_cost.
        score -= (10.0 - (mean_residual / 10.0)) * progress;
    }

    // Final adjustment: penalize spreading items across too many bins if we have many fitting options.
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score -= (fitting_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

