    // that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item can fit into the remaining space, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Harmonic adjustment: prefer bins where the remaining space is close to 
        // a multiple of the next_item_size.
        score -= (post_residual / next_item_size) as f64 * 2.0;
    }

    // 3. Last Chance Logic: If this is the only bin that fits the current item, 
    // it is highly preferred over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 4. Entropy Management: Discourage opening new bins unless the current 
    // open bins are already very full (high mean_residual means bins are empty).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is dynamic based on how much room exists elsewhere.
        score += 30.0 + (mean_residual * 0.5);
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive 
    // about fitting items into existing bins to avoid leftover fragments.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual while avoiding "unusable gaps" (< 10) 
    // and maintaining pressure against opening new bins unnecessarily.

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps too small for any item, i.e., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless no existing bins can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0 + (open_bins_count as f64 * 5.0);
        } else {
            score -= 20.0; // Encourage opening a new bin if nothing else fits
        }
    }

    // 3. Lookahead: If next_item_size is known, penalize bins that cannot fit it
    // if the current post_residual is too small to accommodate the combination.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 25.0;
    }

    // 4. Global efficiency pressure: Penalize high open_bins_count to encourage 
    // filling existing bins rather than spreading items across many bins.
    score += (open_bins_count as f64) * 2.5;

    // 5. Adaptive normalization: If we are near the end of the stream, 
    // lower the penalty for opening new bins to prevent stranding items.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.95 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
