    // 1. Best Fit Decreasing logic: heavily reward smaller residuals (tighter packing)
    // The base score is post_residual, which naturally penalizes large gaps.

    // 2. Penalize opening new bins when existing space is available
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Penalty for opening a new bin: proportional to remaining capacity in existing bins
        // We only open a new bin if the current item is significantly large or the existing bins are too full
        score += mean_residual * 0.5 + (1.0 - progress) * 20.0;
