    // 3. Lookahead integration: Try to keep space for the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // If the next item won't fit, we penalize this placement to keep space for it
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // If the next item fits, we reward it (the gap effectively gets used)
            score -= (next_item_size as f64) * 0.4;
        }
    }

    // 4. Critical threshold management: avoid "orphaning" bins
    // If this is the only bin that can fit the item, prioritize it to avoid wasting a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Dynamic balancing: as we approach the end of the stream, prioritize space density
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // We add a penalty for empty bins to force filling existing ones, 
    // but modulate this penalty by the stream progress and lookahead.
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin opening based on how many alternatives exist.
    // As we approach the end of the stream (progress -> 1.0), we become 
    // more conservative about opening new bins.
    let mut score = post_res.powf(1.5);

    if is_new_bin {
        // New bin penalty: scale by progress to discourage fragmentation early.
        // If fitting_bins_count is 0, this is the only option, so we set a neutral score.
        if fitting_bins_count > 0 {
            score += 100.0 * (1.0 + progress) * (open_bins_count as f64).sqrt();
        }
    } else {
        // Coupling: If the next item is large, we want to preserve larger residuals.
        // We penalize bins that leave a residual smaller than the next item if possible.
        if next_item_size > 0 && post_res < next_item_size as f64 {
            score += (next_item_size as f64 - post_res).powf(1.2);
        }

        // Reward bins that bring the residual closer to the global mean (balancing).
        let dev_from_mean = (post_res - mean_residual).abs();
        score += 0.5 * dev_from_mean;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is small (1-9), it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Harmonic Coupling: If the next item could fit into the current post_residual, 
    // prioritize this bin to preserve the packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Adaptive threshold: If we have many open bins, penalize opening a new one heavily.
    // If bin_residual == bin_capacity, we are evaluating a "New Bin" option.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 35.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // Reward bins that bring the residual closer to the global mean, 
    // keeping bin states balanced.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Last chance logic: If this is the only bin that fits, prioritize it 
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Harmonic Class Logic: Prefer residuals that are multiples of common item sizes (e.g., 20, 25, 50).
    // This creates "slots" for future items.
    if post_residual % 25 == 0 {
        score -= 15.0;
    } else if post_residual % 20 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
