        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Best-Fit logic: Prefer bins that result in a tighter fit (lower post_residual).
    // The base score (post_residual) already incentivizes this, but we reinforce it.
    score += post_residual as f64 * 0.5;

    // 3. Lookahead optimization: If a future item exists, penalize bins that cannot fit it.
    // If post_residual is smaller than the next item, we are "wasting" the bin's potential for the next step.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 4. Global bin pressure: Penalize opening new bins when current bins are underutilized.
    // If we are considering a new bin (bin_residual == bin_capacity), increase cost based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we have other options (fitting_bins_count > 0), make new bins very expensive.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 5. Convergence bias: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late game: Heavily penalize opening new bins to force consolidation.
        if bin_residual == bin_capacity {
            score += 200.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tightly packed.
    // However, if the post_residual is exactly 0, it is a perfect fit.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the current post_residual,
    // strongly reward this bin to minimize future fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward small gaps left over after placing the next item
        score -= (100.0 - diff) * 0.8;
    }

    // 3. New Bin Logic: If this is an empty bin (new bin candidate), penalize it 
    // unless the number of currently open bins is very low or fitting_bins_count is 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have options that fit.
            score += 75.0 + (open_bins_count as f64 * 5.0);
        } else {
            // If no bins fit, this is mandatory; set a neutral/low score.
            score -= 10.0;
        }
    } else {
        // 4. Fragment Avoidance: Penalize leaving a bin with a very small residual 
        // that is unlikely to fit future items (e.g., < 10).
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }

        // 5. Mean-Relative Alignment: Encourage bins to stay close to the average
        // residual of the system to maintain uniform packing pressure.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 6. Progression Bias: As we approach the end of the stream, tighten the 
    // constraints to force higher density.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize extremely tight fits (dead zones)
    // if the residual is small but non-zero, it might be unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 * (1.0 - 0.5 * progress);
