            score += 150.0 * (1.0 - progress);
        } else {
            // If no existing bin fits, opening a new one is necessary; normalize cost.
            score = 50.0;
        }
    }

    // 4. Distribution Balancing: Avoid creating bins that deviate significantly from the mean residual.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * residual_diff;

    // 5. Urgency Calibration: As the stream nears completion, prioritize clearing bins (Best-Fit).
    if progress > 0.85 {
        score += post_residual as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

