    }

    // Lookahead logic: if next_item_size is large, we want to preserve 
    // current bin space if this bin can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else {
            score += (next_item_size as f64) * 0.2;
        }
    }

    // Dynamic preference: As we approach the end of the stream, 
    // prioritize filling existing bins to reduce total count.
    // We dampen the penalty for opening new bins as progress increases.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, but scale it by progress.
        // Early on, we are conservative; later, we might open a bin to avoid poor fits.
        score += 40.0 * (1.0 - progress);
    }

    // Favor bins that are closer to the mean residual to maintain uniform bin states.
    let dev = (post_res - mean_residual).abs();
    score += dev * 0.1;

    // If this is the only bin that can fit the item, reward it to prevent 
    // unnecessary new bin allocation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

