        }
    } else {
        // If it's an existing bin, reward bins that move closer to the mean residual
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // 5. Progression scaling: As we near the end of the stream, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

