    // 3. Global State Awareness: If we have many open bins, penalize opening a new one.
    // If this is a new bin (bin_residual == bin_capacity), increase cost significantly.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Mean Residual Balancing: Avoid bins that deviate significantly from the mean,
    // as they tend to be outliers that are hard to fill later.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Urgency Calibration: As we approach the end of the stream, 
    // prioritize packing tightness over flexibility.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late stage: penalize any residual space
        score += post_residual as f64 * 0.5;
    }

    // 6. Last Chance Heuristic: If this is the only bin that fits the item, 
    // treat it as a high-priority capture unless it's a very poor fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer the smallest post_residual (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // We increase the score of new bins as the stream progresses to discourage 
    // fragmenting space too early, unless the residual is very tight.
    if is_new_bin {
        score += 25.0 * (1.0 + progress);
    }

    // Heuristic: Avoid "Dead Space" (small residuals that cannot fit common items).
    // If post_residual is < 10, it is likely unusable for future items (since min size is 10).
    // We penalize this unless it's a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - progress * 0.5);
    }

    // Lookahead interaction:
    // If we have a next_item, we want to ensure the current bin can fit it if possible.
    if next_item_size > 0 && post_residual < next_item_size {
        // If the current bin will be unable to accommodate the next item, 
        // we penalize this placement relative to the current mean residual.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Pressure normalization:
    // If fitting_bins_count is low (e.g., 1), we are forced to pick this bin. 
    // We reward keeping the mean_residual high to preserve flexibility for larger items.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= (mean_residual - post_residual as f64).abs() * 0.2;
    }

    // Penalize large open bin counts late in the stream to force consolidation.
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

