    // 4. New Bin Threshold: Discourage opening new bins unless current fits are very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the average residual of existing bins is already very low
        // and we are not forced to (i.e., we have fitting bins).
        score += 45.0; 
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 10.0;
        }
        // Penalize opening new bins if the stream is nearing the end
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Mean Residual Balancing: Avoid creating bins that deviate significantly from the mean.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
