    // Stream progression adjustment: As the stream nears the end, 
    // we become increasingly desperate to avoid opening new bins.
    // Penalize the "New Bin" candidate (bin_residual == bin_capacity)
    // proportional to the progress.
    if bin_residual == bin_capacity {
        score += (100.0 * progress) + (open_bins_count as f64 * 2.0);
    }

    // Pressure valve: If this is the ONLY bin that can fit the item, 
    // we reduce its score to ensure we don't accidentally open a new bin 
    // when a valid (though imperfect) fit exists.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
