    }

    // Fragmentation penalty: If the post-residual is small (too small to fit most items),
    // it creates "dead space". We penalize post-residuals that are between 1 and 9
    // as these are statistically unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 10 {
