    }

    // Mean residual coupling: Penalize bins that deviate negatively from the mean,
    // as they are likely "emptier" than average and should be prioritized for larger items.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.5;
