pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny gaps (e.g., < 10) as they are hard to fill later.
    // However, reward tight fits (post near 0) highly.
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Incorporate lookahead: if the next item fits into the current post_residual, 
    // prioritize this bin to preserve future capacity.
    let lookahead_bonus = if next_item_size > 0 && (post_residual >= next_item_size) {
        -15.0 * (1.0 - progress)
    } else {
