    };

    // If this is the last chance for the current item (fitting_bins_count == 1), 
    // reduce the penalty for poor fits to avoid unnecessary new bins.
    let urgency_factor = if fitting_bins_count <= 1 { 0.5 } else { 1.0 };

    // Non-linear coupling: favor smaller post_residuals but scale by stream progress
    // to become more aggressive at packing as we approach the end of the stream.
    let base_score = post * (1.0 + 0.5 * progress);

    // Penalize opening a new bin (where bin_residual == bin_capacity)
