            score -= 5.0; 
        }
    } else {
        // New Bin Penalty: Make opening a new bin expensive unless fitting_bins_count is low
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // 4. Global Efficiency: If the bin is becoming very empty compared to the mean, 
    // penalize placing items there to favor packing denser bins.
    if (post_residual as f64) > mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (The "Dead Space" avoidance)
    // We penalize post_residuals that are too small to fit typical future items (< 10)
    // but large enough to be wasted (e.g., 1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead matching: If the next item fits perfectly into the remaining space
    // or is close to filling it, we prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that create a "perfect fit" for the next item
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize bins that cannot fit the next item if they could have
            score += 20.0;
        }
    }

    // 3. Global Bin Management:
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it
    // unless the current fitting bins are very poor (high residuals).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Penalty for opening a new bin is scaled by how well the current 
            // open bins are utilized (mean_residual). 
            // If mean_residual is low, we are doing well, so we penalize opening a new bin.
            score += 60.0 + mean_residual;
        }
    }

    // 4. Fitting Pressure:
    // If this is the only bin that can fit the item, we must prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
