            score += 45.0 + (progress * 30.0);
        }
    } else {
        // 4. Fitting Pressure: If this is the only bin that can fit the item, 
        // give it a strong incentive to prevent unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // 5. Mean Deviation: Discourage bins that deviate significantly from the current 
        // average residual (avoiding "fragmented" bin states).
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
