        }
    }

    // 4. Distribution Balancing: Use the mean_residual to avoid creating highly asymmetrical bins.
    // If this bin's post_residual is significantly lower than the global mean, it's a good candidate.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Progression Scaling: As the stream nears the end, be more aggressive with tight packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
