        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If next_item_size fits in post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Harmonic alignment: Reward post_residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // This helps keep bins "aligned" for future items.
    let harmonic_penalty = (post_residual % 25) as f64 * 0.5;
    score += harmonic_penalty;

    // 4. If this is a new bin (bin_residual == bin_capacity):
    // Only open if the mean residual is already quite low (bins are full),
    // otherwise, penalize opening a new bin to force packing into existing ones.
    if bin_residual == bin_capacity {
        score += 35.0 + (mean_residual * 0.5);
        // Late stage: be more aggressive opening new bins if we are nearing the end
        score -= progress * 20.0;
    }

    // 5. Fitting count pressure: If this is the only bin that fits the item (fitting_bins_count == 1),
    // give it a massive boost to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // 6. Global efficiency: If we have many open bins, prioritize filling the ones with the lowest residuals
    // to reduce the total count of active bins (Best-Fit behavior).
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
