pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) as the stream progresses,
    // unless the item is very large or we are late in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 45.0 + (item_size as f64 * 0.5)
    } else {
        0.0
    };

    // Calculate how well the next item fits into the remaining space
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 0.8
    } else {
        0.0
    };

    // Prefer bins that leave little space (Best Fit), but penalize extreme tightness (0-3 range)
    // if we have many open bins, as it might strand small items.
    let tightness_penalty = if post_residual < 4 {
        15.0 * (open_bins_count as f64 / 10.0)
    } else {
        post_res * 0.5
    };

    // Interaction term: favor bins that bring the bin's residual closer to the global mean
    let mean_alignment = (post_res - mean_residual).abs() * 0.2;

    // Final score: minimize this value
    // We favor bins where post_residual is low (Best Fit) but avoid creating 
    // unusable gaps for future items (Lookahead) and normalize against stream progress.
    tightness_penalty + new_bin_penalty + lookahead_penalty + mean_alignment
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
