        } else {
            // Penalize bins that block the next item from fitting comfortably
            score += 15.0;
        }
    }

    // 3. Global state balancing: Avoid opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy "entry cost".
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.2);
    } else {
        // If it's an existing bin, reward it if it's "tighter" than the current mean
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 4. Scarcity handling: If this is the last bin that can fit the item, 
    // prioritize it to prevent being forced into a new bin later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progress scaling: As the stream nears the end, become more aggressive 
    // about filling bins to reduce the total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
