    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items (10-20)
    // If the post_residual is between 1 and 9, it is highly likely to become unusable "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Integration: If the next item is large, avoid creating a residual that is too small for it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 30.0;
    }

    // 3. Open Bins Pressure: Discourage opening new bins unless the fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), add a penalty proportional to current open bin count.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 1.5);
    } else {
        // 4. Best-Fit Bias: Reward placing items in bins that bring the residual closer to the mean_residual.
        // This keeps the bins balanced.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // 5. Urgency factor: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress and open bins
    if is_new_bin {
        score += 25.0 + (progress * 15.0) + (open_bins_count as f64 * 0.5);
    } else {
        // Lookahead heuristic: favor bins where post_residual matches next_item_size
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score += diff * 0.4;

            // Reward perfect fit for the next item
            if post_residual == next_item_size {
                score -= 10.0;
            }
        }

        // Penalty for creating "sliver" space that is too small for any likely item (dead space)
        // If post_residual is small but > 0, it's often a bad fit unless it's 0
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // Influence of mean_residual: avoid deviating too far from the average load
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;

        // If this is the last fitting bin, prioritize it to avoid opening a new one unnecessarily
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: reward smaller residuals (tighter packing)
    // We want to minimize post_residual, so it stays as is.

    // 2. Lookahead Coupling: 
    // If we have a next item, penalize residuals that are too small to fit it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin becomes "useless" for the next item.
            // Penalize this more towards the end of the stream.
            score += (next_item_size - post_residual) as f64 * (1.0 + progress);
        } else {
            // Reward bins that can accommodate the next item (synergy).
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // 3. Fragmentation Penalty:
    // If post_residual is small but not zero (e.g., 1-5), it's "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Global State Awareness:
    // If this is the only fitting bin, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. New Bin Thresholding:
    // If checking an empty bin, add a significant cost to discourage opening it 
    // unless the fit in existing bins is truly disastrous.
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.2);
    }

    // 6. Density Balancing:
    // As the stream progresses, favor packing tighter to avoid trailing orphans.
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize Best Fit (lower post_residual)
    let mut score = post_res;

    // Penalty for creating a "fragment" (very small, unusable residual)
    // We penalize post_residual values between 1 and 9 significantly, 
    // as these are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item is large, favor bins that leave enough space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalty for stranding an item if this is the only bin that could have fit it
            score += 15.0;
        }
    }

    // Dynamic thresholding based on stream progress:
    // As the stream progresses, become more conservative about opening new bins.
    // If fitting_bins_count is 1, avoid opening a new bin at all costs.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Favor bins that align with the global mean residual to keep bin levels balanced
    let deviation = (post_res - mean_residual).abs();
    score += 0.5 * deviation * (1.0 + progress);

    // Penalize opening a new bin (bin_residual == bin_capacity) increasingly as the stream finishes
    if bin_residual == bin_capacity {
        score += 25.0 + (30.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
