            score -= (bin_capacity - post_residual) as f64 * 0.2;
        } else {
            // Penalize bins that block the next item from fitting comfortably
            score += 15.0;
        }
    }

    // 3. Density Balancing: If we have many open bins, prioritize filling the tightest ones.
    // fitting_bins_count == 1 acts as a "forced fit" signal.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 4. New Bin Thresholding: Discourage opening new bins unless the current residual is very poor.
    if bin_residual == bin_capacity {
