pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Current progress factor (0.0 to 1.0)
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for common items (below 10)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 + progress);
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Dynamic aversion to opening new bins
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to (fitting_bins_count == 0)
        // or if our current mean_residual is very high (meaning we have space elsewhere)
        if fitting_bins_count > 0 {
            score += 150.0 * (1.0 - progress);
        } else {
            score -= 50.0;
        }
    }

    // 4. Global state coupling: If we have many open bins, penalize small residual leftovers
    // to encourage packing tightly into existing bins rather than spreading thin.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. If this bin is the last chance to fit the item (fitting_bins_count == 1), 
    // reward it to prevent opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Final adjustment: penalize bins that deviate significantly from the mean residual
    // to keep the packing density consistent across all open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" choice heavily unless we are in the early stage of the stream
    // and the current fit is extremely poor (large post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = if is_new_bin {
        // Base cost for opening a new bin is high.
        // We reduce this cost slightly as we reach the end of the stream to avoid
        // leaving many half-empty bins at the very end.
        35.0 + (1.0 - progress) * 25.0
    } else {
        // For existing bins, we favor "Best Fit" (smallest post_residual).
        // We apply a non-linear penalty for leaving space that is too small for
        // the average item or the next incoming item.
        let penalty = if next_item_size > 0 && post_residual < next_item_size {
            // Penalize creating "dead space" that cannot fit the immediate next item.
            20.0 * (1.0 - (post / next_item_size as f64))
        } else {
            0.0
        };

        post + penalty
    };

    // Coupling: If we have many open bins, we become more desperate to fill existing ones
    // rather than opening new ones, by biasing against high residuals.
    if !is_new_bin {
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Refinement: If this is the last chance for the current item (fitting_bins_count == 1),
    // heavily reward taking the fit to avoid a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 15.0;
    }

    score
}

