    };

    let mut score = post + dead_space_penalty + lookahead_penalty + new_bin_penalty + balance_penalty;

    // Favor bins that are the last chance to fit the current item if they have decent space
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

