        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead optimization: If next_item_size is known, reward bins that can accommodate it.
    // If post_residual is close to next_item_size, we favor this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;

        // If the bin can fit the current item AND the next item, heavily prioritize it.
        if post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // 3. New Bin Management:
    // If this is a new bin (bin_residual == bin_capacity), penalize it relative to how many 
    // existing bins can already fit the item. Only open a new bin if existing fits are terrible.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64 * 40.0) + (open_bins_count as f64 * 2.0);
    }

    // 4. Global distribution alignment:
    // If the post_residual is significantly higher than the mean_residual, 
    // this bin is "emptier" than average, which is good for future flexibility.
    if (post_residual as f64) > mean_residual {
        score -= (post_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Progression scaling: 
    // As we approach the end of the stream, prioritize tight packing (Best Fit) 
    // over maintaining empty space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (tighter fit).
    // The base score is already post_residual.

    // 2. Penalty for creating "dead space":
    // If post_residual is small but not zero, it's often hard to fill.
    // Penalize values in the 1-9 range (too small for most items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead integration:
    // If we have a next item, check if it fits in the current post_residual.
    // If next_item_size fits perfectly, reward this bin heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
