        } else {
            // If it doesn't fit, penalize slightly to prefer bins that might accommodate it.
            score += 5.0;
        }
    }

    // 4. Global state and progression:
    // As the stream nears the end, become more aggressive with packing (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // 5. New bin handling:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless fitting_bins_count is 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one works.
            score += 150.0;
        } else {
            // If no existing bins work, prioritize the new bin.
            score -= 50.0;
        }
    }

    // 6. Mean residual balancing:
    // Favor bins that keep the mean residual balanced to avoid outliers.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
