    }

    // Coupling with global state: if many bins are open, penalize opening new ones.
    // If few bins are open, be more lenient.
    score += (open_bins_count as f64).powf(1.2);

    // Reward bins that bring the current residual closer to the global mean,
    // reducing variance in bin fill-levels to prevent fragmented space.
    let deviation = (post_res - mean_residual).abs();
    score += 0.5 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
