    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is highly likely to be wasted.
    // We penalize this heavily to favor tighter fits or leaving larger gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bins Pressure: Penalize opening new bins when current ones can fit the item.
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 0.5);
        } else {
            score -= 10.0; // Encourage opening a new bin if nothing else fits
        }
    }

    // 3. Lookahead Coupling: If the next item is large, favor keeping bins with larger residuals.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0; // Penalty for making the bin unable to fit the next item
        }
    }

    // 4. Mean Residual Balancing: Favor bins that are closer to the current average fullness.
    // This maintains a uniform distribution of residuals across the bin set.
    let current_residual = bin_residual as f64;
    score += (current_residual - mean_residual).abs() * 0.1;

    // 5. Progression Scaling: As the stream nears the end, prioritize closing bins (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= post_residual as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

