    // However, heavily penalize creating "dead space" (residuals < 10) 
    // unless it results in a perfect fill (0 residual).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual == 0 {
        score -= 20.0;
    }

    // 2. Lookahead matching: reward placements where the post_residual 
    // can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
            // Reward exact matches for the lookahead item
            if post_residual == next_item_size {
                score -= 40.0;
            }
        }
    }

    // 3. Global Bin Management:
    // Avoid opening new bins if there are existing bins that fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // High penalty for opening a new bin prematurely
            score += 150.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 4. Distributional balance:
    // Penalize bins that deviate significantly from the mean residual.
    // We want to keep bins packed similarly to the overall state.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // 5. Progression adjustment:
    // As we approach the end of the stream, prioritize closing bins (lower residual)
    // more aggressively to avoid leaving stragglers.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
