    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post-residual (Best Fit principle)
    let mut score = post.powf(1.5);

    // Penalty for creating "dead zones" (small residuals that cannot fit common items)
    // As progress increases, we become more risk-averse about leaving small gaps.
    if post > 0.0 && post < 15.0 {
        score += (20.0 * (1.0 + progress)) / (post + 1.0);
    }

    // Lookahead logic: if next_item_size is large, favor bins that leave enough space for it
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 50.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding for opening new bins:
    // When bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are "too full" to be efficient 
        // or if we are early in the stream.
        let efficiency_penalty = (open_bins_count as f64 * 5.0) / (1.0 + progress);
        score = 45.0 + efficiency_penalty;
    } else {
        // Reward fitting into existing bins to minimize open_bins_count
        score -= (fitting_bins_count as f64).sqrt() * 10.0;
    }

    // Penalize extreme fragmentation relative to the mean
    if post > mean_residual {
        score += (post - mean_residual).powf(1.2);
    }

    score
}

