    // 2. Lookahead Synergy: Reward bins that become a perfect fit for the next item
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // If this bin can fit the next item after current, heavily prioritize it
        if post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // 3. Fragmentation Avoidance: If post_residual is small but > 0, it's often wasted space.
    // Penalize "slivers" (e.g., 1-9 remaining) unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Global Density Control: If we have many open bins, prioritize finishing them (lowering mean_residual)
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. New Bin Policy: Discourage opening a new bin unless the current item is large 
    // or the existing fitting options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other bins can accommodate the item
