pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // We add a non-linear penalty for creating "fragmented" space (small, unusable residuals)
    // Fragmented space is defined as residuals < 10 (the minimum item size)
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        100.0 * (1.0 - (post / 10.0))
    } else {
        0.0
    };

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // prioritize this bin to reduce total bin count.
    let lookahead_bonus = if next_item_size > 0 && (post_residual >= next_item_size) {
        -50.0 * (1.0 - (post / bin_capacity as f64))
    } else {
        0.0
    };

    // Global state coupling: As the stream progresses, prioritize filling 
    // bins more tightly to avoid leaving many bins open late in the stream.
    let progress_weight = 20.0 * progress;
    let density_penalty = progress_weight * (post / bin_capacity as f64).powf(2.0);

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless the fit in other bins is extremely poor (high fragmentation).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        150.0 - (50.0 * (open_bins_count as f64 / 10.0).tanh())
    } else {
        0.0
    };

    let score = post + fragmentation_penalty + lookahead_bonus + density_penalty + new_bin_penalty;
