    // If we have many open bins, penalize opening new ones (where bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // Encourage using existing bins that are close to the mean residual
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Last Chance Heuristic:
    // If this is the only bin that fits the current item (fitting_bins_count == 1),
    // heavily bias towards taking it to avoid creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining after placement.
    // Lower residual is generally better (Best-Fit approach).
    let mut score = post;

    // Penalty for creating 'dead space' (small, unusable residuals).
    // Small residuals (1-9) are highly problematic because item sizes start at 10.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if next_item_size is large, we want to preserve space in the current bin
    // if possible, or prioritize bins that can accommodate the next item.
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            // Reward bins that can accommodate the next item
            score -= 20.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize bins that will be too small for the next item
            score += 10.0;
        }
    }

    // Dynamic pressure: as the stream progresses, prioritize closing bins (lower mean_residual).
    // If a bin is significantly emptier than the average, it is a poor candidate late in the stream.
    if progress > 0.5 {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * progress;
    }

    // Heuristic for new bin opening:
    // If the bin is new (bin_residual == bin_capacity), apply a heavy penalty that decreases
    // as the stream progresses, but is generally high to force Best-Fit behavior.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress);
    }

    // Final constraint: if this is the only fitting bin, reduce the penalty for poor fits
    // to prevent unnecessary new bin openings when it is the last chance.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
