    if (post_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    }

    // 5. New Bin Aversion: Heavily penalize opening a new bin unless necessary.
    // Only open a new bin if the current fit is extremely poor (post_residual > 40).
    if bin_residual == bin_capacity {
