pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space: we prefer smaller residuals (Best Fit)
    // We add a non-linear penalty for "wasted" space that is too small to fit future items.
    // If post_residual is small but > 0, it creates "dead space" that is hard to fill.
    let dead_space_penalty = if post_res > 0.0 && post_res < 10.0 {
        20.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Interaction term: If we are late in the stream, be more aggressive about filling bins (lowering score).
    // We penalize opening new bins (bin_residual == bin_capacity) more as we approach the end.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        40.0 + (progress * 60.0)
    } else {
        0.0
    };

    // Lookahead logic: if the next item is large, we want to reserve space for it.
    // If current post_residual is less than next_item_size, we penalize the placement.
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
        (next_item_size as f64 - post_res) * 0.5
    } else {
        0.0
    };

    // Normalize against mean_residual to favor bins that are already "tight"
    let density_adjustment = (post_res - mean_residual).powf(1.5) * 0.1;

    // Final score: prioritize small residuals, penalize new bins, and account for lookahead
    post_res + dead_space_penalty + new_bin_penalty + lookahead_penalty + density_adjustment
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
