    // We favor smaller post_residuals (tighter fits).
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Integration: If next item exists, reward bins that can accommodate it.
    // If post_residual is >= next_item_size, we create a "future-proof" slot.
    if next_item_size > 0 {
