    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strongly discourage opening a new bin if other options exist
            score += 150.0 * (1.0 - progress * 0.5);
        } else {
            // Neutralize score for mandatory new bin
            score = 50.0;
        }
    }

    // 4. Global Density Balancing:
    // If mean_residual is high, we are being too loose; favor tighter fits.
    // If mean_residual is low, we have little room; prioritize surviving the next items.
    if mean_residual < 20.0 {
        score -= (post_residual as f64) * 0.5;
    }

    // 5. Critical Constraint:
    // If this bin is the only one that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
