pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9 range)
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Reward bins that align with the next item to minimize future bin openings
    let lookahead_alignment = if next_item_size > 0 {
        let diff = (post_res - next_item_size as f64).abs();
        // Lower score if the post_residual is close to the next item size
        (diff * 0.5) - (1.0 / (1.0 + diff))
    } else {
        0.0
    };

    // Dynamic pressure: If progress is high, prioritize tight packing (Best Fit)
    // If progress is low, be more lenient to keep options open
    let tightness_weight = 1.0 + (progress * 2.0);

    // Base score: prioritize smaller post_residual (Best Fit)
    // Adding non-linear interaction between mean_residual and current fit
    let base_score = post_res * tightness_weight;

    // Penalize opening a new bin unless the fit is extremely poor
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // Only open new bin if we have many open bins already or if the fit is bad elsewhere
        (50.0 * (1.0 - progress)) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Interaction with mean_residual to avoid "wasting" bins that are already well-filled
    let mean_res_penalty = if !is_new_bin && post_res > mean_residual {
        (post_res - mean_residual) * 0.5
    } else {
        0.0
    };

    base_score + fragmentation_penalty + lookahead_alignment + new_bin_penalty + mean_res_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
