pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty:
    // If the post_residual is small (e.g., < 10), it is likely to remain unused.
    // We penalize these "sliver" residuals heavily to force tight packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy:
    // If we know the next item, we reward bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward bins that can potentially fit the next item
        } else {
            score += 15.0; // Penalize bins that will definitely block the next item
        }
    }

    // 3. Open Bins Pressure:
    // Minimize the number of bins by penalizing the use of a new bin 
    // when existing bins could still fit the item.
    if bin_residual == bin_capacity {
        score += 40.0; // Resistance to opening new bins
        // If many bins are already open, increase resistance to opening yet another.
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. Mean Residual Balancing:
    // Prefer bins that stay close to the average utilization to prevent 
    // outliers (highly empty vs highly full bins).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Last Chance Logic:
    // If this is the only bin that can fit the item, prioritize it to avoid
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize based on current fragmentation to prevent premature bin opening.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already very tight (high utilization).
        score += 150.0 - (mean_residual * 1.5);
    } else {
        // 2. Best-Fit logic: Prefer bins that result in smaller post_residuals.
        // Penalty for creating a "dead zone" (e.g., residual space < 10 which is too small for most items).
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }

        // 3. Lookahead matching: If the next item fits perfectly into the post_residual, reward this placement.
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            // Reward exact fit (diff == 0) heavily.
            score -= (50.0 / (diff + 1.0));

            // If the next item cannot fit in this post_residual but could have fit in the pre-residual,
            // we penalize the current placement to save the space for the next item.
            if post_residual < next_item_size && bin_residual >= next_item_size {
                score += 25.0;
            }
        }
    }

    // 4. Global progress scaling: As the stream nears the end, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    // 5. Avoid creating too many open bins if we have a high count already.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that likely won't fit future items)
    // We penalize residuals in the range [1, 9] heavily as they are rarely useful.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If a future item exists, prioritize bins that leave
    // space for it, or avoid bins that leave too little space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward perfect fit or ability to fit the next item
        } else if post_residual > 0 {
            score += 15.0; // Penalize "wasting" a bin that can't fit the next item
        }
    }

    // 3. Dynamic Thresholding: As we approach the end of the stream, prioritize closing
    // existing bins rather than opening new ones to maximize bin utilization.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have fitting bins available
        score += (fitting_bins_count as f64 * 40.0) * (1.0 - progress * 0.5);
    }

    // 4. Global State Balancing: Use mean_residual to prevent uneven bin filling.
    // If this bin is significantly emptier than the average, prioritize filling it.
    let residual_diff = bin_residual as f64 - mean_residual;
    if residual_diff > 0.0 {
        score -= residual_diff * 0.5;
    }

    // 5. Final adjustment: Strongly favor tight fits (Best Fit principle)
    // post_residual is already part of the score; we amplify the penalty for large remaining space.
    score += (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a 'dead' zone (small, unusable residual space).
    // If post_residual is < 10, it's likely unusable as min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // reward this bin heavily to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Dynamic thresholding: as the stream progresses, become more aggressive 
    // about filling bins tightly to avoid trailing open bins.
    let density_pressure = (open_bins_count as f64 / (step_index as f64 + 1.0).sqrt()) * 10.0;
    score += density_pressure * progress;

    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // heavily unless fitting_bins_count is zero (forced new bin).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty to prevent opening new bins unnecessarily.
            score += 150.0 * (1.0 - progress);
        } else {
            // No other choice, normalize to a low score.
            score = -100.0;
        }
    }

    // Reward bins that align with the mean_residual to keep bin states uniform.
    let mean_diff = (post - mean_residual).abs();
    score += mean_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual
    // 2. Penalty for creating "orphaned" space (dead space < 10, as items are >= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead optimization: If next_item can fit in current post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
