    // 4. Harmonic thresholding: Favor bins that leave space divisible by common item sizes
    // This reduces fragmentation by aligning residuals with potential future item clusters
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. New bin management: 
    // If we have very few fitting bins, avoid opening new bins unless necessary.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one can fit the item
            score += 150.0;
        } else {
            // Baseline cost for opening a new bin
            score += 20.0;
        }
    }

    // 6. Scale by progression: As we approach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items (10-25 range)
    // If post_residual is in (0, 10), it is highly likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when current bins are underutilized.
    // If we are considering a new bin (bin_residual == bin_capacity), increase cost if we have many bins open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // If there are other bins that could fit this item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Density Balancing: Favor bins that keep the mean residual low to avoid fragmented bin states.
    // If this bin's post_residual is significantly better than the global mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Progression Weighting: As the stream nears the end, be more aggressive about closing bins 
    // (avoiding new bins even if the fit is suboptimal).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the post-placement residual (Best Fit strategy)
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" that is too small for any likely future item
    // If post_residual is smaller than the minimum expected size (10), it's often wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead matching: If the next item fits perfectly into this post_residual, 
    // prioritize this bin strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward bins that maintain enough space for the next item
            score -= 10.0;
        }
    }

    // 3. Global efficiency: If we are nearing the end of the stream, 
    // prioritize closing bins (lower mean_residual) to avoid leaving too many half-full bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (mean_residual - post_residual as f64) * 0.5;
    }

    // 4. New bin penalty: Only open a new bin if the fit in existing bins is objectively poor.
    // If this is a new bin (residual == capacity), add a significant penalty to force 
    // filling existing bins unless they are all very poor fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If there are many open bins that could fit this, penalize the new bin even more.
        score += (fitting_bins_count as f64) * 5.0;
    }

    // 5. Prefer bins that are already closer to being full (lower residual) 
    // to minimize the number of active open bins.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

