        if post_residual > 0 && post_residual < 10 {
            score += 50.0;
        }

        // Dynamic pressure: If we have many open bins, prioritize closing them 
        // by choosing the bin that leaves the least residual space (Best Fit).
        score += (open_bins_count as f64) * 0.1;
    }

    // Adjust for global state: as we approach the end of the stream, 
    // be more aggressive about filling existing bins to minimize total count.
    if progress > 0.8 {
        score -= (100.0 - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
