        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Urgency: As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "slivers" (dead space too small for any likely item)
    // We penalize post_residuals that are small but non-zero.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Heuristic: Prefer tightly packed bins (Best Fit principle)
    // Low post_residual is usually good, but we adjust based on future needs.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= (next_item_size as f64 * 0.8);
        } else {
            // Penalize bins that cannot accommodate the next item if we have capacity elsewhere
            score += 15.0;
        }
    }

    // Global state awareness: If we are near the end of the stream, 
    // prioritize packing items into existing bins to minimize total count.
    if progress > 0.8 {
        score -= (open_bins_count as f64 * 2.0);
    }

    // New bin logic: Only open a new bin if the current fit is extremely poor
    // or if we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty to open a new bin if an existing one could work
            score += 60.0 + (mean_residual * 0.5);
        } else {
            // No choice, must open
            score = 0.0;
        }
    }

    // Penalize bins that deviate significantly from the mean residual (load balancing)
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

