    let mut score = post;

    // Penalty for creating "dead space" (small, unusable residuals)
    // We penalize residuals that are smaller than the smallest possible item (10)
    // but larger than 0, as these are often wasted.
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item is large, prioritize bins that keep 
    // enough space to accommodate it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
