        score += 40.0 * progress;
    }

    // Encourage filling bins that are already "half-empty" to keep the distribution
    // of residuals centered, rather than fragmenting many bins.
    let residual_deviation = (post - mean_residual).abs();
    score += 0.5 * residual_deviation;

    // If this is the only bin that can fit the item, give it a significant priority boost
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
