    // 3. Harmonic Class Logic: penalize bins that leave "awkward" remainders.
    // Remainders that are too small to fit any items (e.g., < 10) are high-penalty dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. New Bin Threshold: Discourage opening a new bin unless the current 
    // mean_residual is very low, or the current fit is extremely poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 45.0;

        // If existing bins have plenty of space, penalize opening a new one further
        if mean_residual > 20.0 {
            score += mean_residual * 1.5;
        }
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive 
    // about packing into existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 6. Avoid "Last Chance" Trap: If this is the only bin that fits the item 
    // (fitting_bins_count == 1), prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is too small to fit any common item (e.g., < 10),
    // it creates "splinters". We penalize these heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Integration: If the next item doesn't fit in the remaining space,
    // we penalize this bin more than one that leaves space for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Global Pressure: As the stream progresses, we become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    let open_bin_penalty = (open_bins_count as f64) * 2.5 * (1.0 - progress);

    // 4. New Bin Logic: If this is a new bin (residual == capacity), we only choose it
    // if the existing open bins are "bad" fits (high post_residual or high open_bins_count).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high, but scales with existing open bins.
        score = 45.0 + (open_bins_count as f64 * 5.0);
    } else {
        // For existing bins, add the global pressure.
        score += open_bin_penalty;
    }

    // 5. Fitting Constraint: If this is the only bin that fits the item, reward it to avoid
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual. 
    // We want to minimize this (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can accommodate the item.
            score += 200.0 + (open_bins_count as f64 * 10.0);
        } else {
            // If it's a new bin and no other options exist, it's a forced move.
            score = 0.0;
        }
    } else {
        // Reward placements that leave a residual matching the next item (Lookahead).
        // This promotes tight packing for the subsequent step.
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score += diff * 0.5;
        }

        // Penalty for creating 'dead space' (residuals too small to fit common items).
        // If post_residual is < 10, it's likely unusable.
        if post_residual < 10 && post_residual > 0 {
            score += 50.0;
        }

        // Heuristic: Prefer bins that are closer to the mean residual of all open bins,
        // to maintain uniform wear/filling across bins (load balancing).
        let dev_from_mean = (post_residual as f64 - mean_residual).abs();
        score += dev_from_mean * 0.2;

        // If this is the last chance bin (fitting_bins_count == 1), 
        // prioritize filling it to avoid leaving it stranded.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
