    if fitting_bins_count > 0 {
        // If we have options, prefer bins where the remaining space is closer to the mean.
        // This balances the load across open bins.
        score += (post_residual as f64 - mean_residual).abs() * 0.5;

        // Penalize opening a new bin if we are near the end of the stream.
        if bin_residual == bin_capacity {
            score += 40.0 * (1.0 - progress);
        }
    } else {
        // If no existing bin fits, we MUST open a new one.
        // Normalize the new bin score to be competitive but not overly greedy.
        score = 30.0;
    }

    // 4. Global State: Penalize opening too many bins early on.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

