    // Reward packing efficiency by favoring smaller post_residuals
    let mut score = post * post;

    // Lookahead logic: if the next item can fit in the current post_residual, 
    // reward this bin to avoid fragmentation later.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
