    }

    // Dynamic pressure: As the stream progresses, increase the penalty for opening new bins
    // unless the residual is very tight.
    if bin_residual == bin_capacity {
        score += 2500.0 * (1.0 + progress);
    } else {
        // Encourage using existing bins that have a residual similar to the global mean,
        // reducing the variance of bin fillings.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 10.0 * dev;
    }

    // If this is the last fitting bin, prioritize it to avoid creating a new bin
