}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // We favor smaller post_residuals to keep bins tight.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic/Residual coupling: Penalize post_residuals that are "unlucky" 
    // for common item sizes (e.g., leaving a gap smaller than the mean item size).
    if post_residual > 0 && (post_residual as f64) < (bin_capacity as f64 - mean_residual) {
        score += 15.0;
    }

    // 3. Lookahead logic: If next_item_size fits in the current post_residual, 
    // heavily reward this bin to keep the packing sequence dense.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Thresholding: Avoid opening new bins unless the fit is extremely poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // to discourage starting new bins if an existing one is available.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0;
        }
    }

    // 5. Fitting constraints: If this is the only bin that fits the item (fitting_bins_count == 1),
    // give it a massive priority boost to prevent wasted space in other bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 6. Harmonic refinement: Use modulo to penalize gaps that are awkward fractions of capacity.
    // This targets the "fragmentation" problem common in bin packing.
    score += (post_residual % 10) as f64 * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "orphaned" gaps (1-9) 
    // that cannot fit even the smallest items, while scaling based on bin density.

    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (gaps < 10 are effectively unusable for input range 10-80)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Pressure factor: If we have many open bins, penalize opening a new one 
    // unless the current fit is extremely tight (Best Fit logic).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current mean residual is already high 
        // or if we have very few open bins to begin with.
        score += (open_bins_count as f64 * 2.0) + (mean_residual * 0.5);
    } else {
        // For existing bins, reward fits that leave the residual close to the mean
        // to keep bin levels balanced.
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    // Lookahead: If the next item is large, favor bins that leave enough space for it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0; 
    }

    // Critical constraint: If this is the last fitting bin, prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Progress weighting: As we approach the end of the stream, be more conservative.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

