    // Penalize empty bin opening unless necessary.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Heavy penalty for opening new bin if existing ones fit
        } else {
            score -= 20.0; // Incentivize starting a new bin if no other options exist
        }
    }

    // 2. Lookahead matching: If the next item fits perfectly in the remaining space, 
    // prioritize this bin to prepare for the subsequent step.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= (50.0 - diff).max(0.0);
    }

    // 3. Balance consolidation: Penalize bins that deviate significantly from the mean_residual.
    // We want to keep residuals uniform to increase the probability of fitting future large items.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // 4. Scarcity adjustment: If only one bin can fit this item, favor it to avoid 
    // wasting that unique opportunity.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize closing 
    // bins (lower post_residual) over keeping bins open for potential future items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
