    // As the stream progresses, we become more aggressive in packing to avoid trailing empty bins.
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = if is_new_bin {
        (1.0 - progress) * 150.0 + (progress * 20.0)
    } else {
        post
    };

    // Reward bins that leave space for the lookahead item (next_item_size)
    // If the current placement makes the bin unable to fit the next item, penalize it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Heuristic: If this is the only bin that fits the item (fitting_bins_count == 1),
    // prioritize using it to keep the bin count low, unless the fit is extremely poor.
    if fitting_bins_count == 1 && !is_new_bin {
