    }

    // Balance the residual against the global state: 
    // If our average residual is high, we are being too loose; prioritize tighter fits.
    // If our average residual is low, we are being too tight; tolerate larger post_residuals.
    let residual_balance = (post - mean_residual) * (1.0 - progress);
    score += residual_balance;

    // Non-linear penalty for creating "dead zones" (very small residuals that are unlikely to be filled)
    // We define a dead zone as space < 10.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

