    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        score = 45.0;
        // If we have many open bins that are nearly empty, reusing them is better.
        if open_bins_count > 0 && mean_residual > 50.0 {
            score += 40.0;
        }
    }

    // 6. Harmonic Class Bias: Favor filling bins to near-capacity (Best-Fit principle).
    score += (post_residual as f64) * 0.1;

