    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 6. Final progression scaling: As we approach the end of the stream, 
    // become more aggressive in minimizing the number of bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

