}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that are too small to fit future items.
    // If post_residual is in (0, 10), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, 
    // prioritize this bin to preserve bin density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary (fitting_bins_count == 0).
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless there are no other options.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 20.0; // Preference to open a new bin if nothing else fits well
        }
    }

    // 4. Mean Residual Balancing: Penalize bins that deviate significantly from the mean 
    // residual of active bins to encourage uniform packing.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Progression Weighting: As the stream nears completion, become more aggressive 
    // about filling existing bins to reduce tail-end waste.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals
    // but reward those that leave exactly 0 space (perfect fit).
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead matching: If the post_residual can fit the next item, 
    // significantly lower the score to encourage this pairing.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Penalty for opening a new bin (bin_residual == bin_capacity).
    // Only open a new bin if the existing bins are highly fragmented.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && (mean_residual > (item_size as f64 * 0.5)) {
            score += 40.0;
        } else {
            score += 85.0;
        }
    }

    // 4. Fragment avoidance: Penalize leaving a residual that is too small for 
    // most items (e.g., < 10) unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 5. Dynamic density: As the stream progresses, prioritize closing bins
    // by favoring placements that bring bin_residual closer to 0.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    // 6. Last-chance logic: If this is the only bin that can fit the item,
    // reduce the penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: Favor bins that result in smaller residuals (tighter packing)
    // We start with post_residual, which is already a good proxy for Best Fit.

    // 2. Lookahead Penalty/Reward: If the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New Bin Thresholding: Penalize opening a new bin unless the current residual is very poor.
    if bin_residual == bin_capacity {
        // If we are at the end of the stream, be more aggressive with new bins.
        // Otherwise, make it harder to open a new bin if we have many fitting options.
        let threshold = 40.0 + (progress * 30.0);
        score += threshold;
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 4. Global State Awareness: If the bin's post_residual is significantly worse than the mean,
    // we penalize it to force consolidation into more efficient bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Fragmentation Avoidance: If this is the only bin that fits the item (fitting_bins_count == 1),
