    }

    // 6. Final scaling based on remaining capacity to avoid "dead" space
    // Penalize post_residuals that are too small to fit any common item (e.g., < 10)
    // as these are often "trapped" space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize empty bins (creating new bins) more as we approach the end of the stream
    // to encourage consolidation.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 25.0 + (progress * 50.0) } else { 0.0 };

    // Best-Fit Decreasing logic: favor small residuals (post_residual -> 0).
    // The quadratic term penalizes large gaps that are difficult to fill later.
    let gap_penalty = post * post * 0.015;

    // Lookahead coupling: If the next item fits into the current post_residual, 
    // reward this bin to keep the next item's placement options flexible.
    let lookahead_reward = if next_item_size > 0 && (post_residual >= next_item_size) {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Interaction term: If this is the last fitting bin, prioritize it to avoid 
    // fragmenting space in other bins unnecessarily.
    let last_chance_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -20.0
    } else {
        0.0
    };

    // Normalize against mean_residual to avoid over-filling bins that are already 
    // very tight compared to the average state of the system.
    let density_adjustment = if post < mean_residual {
        -5.0
    } else {
        5.0
    };

    gap_penalty + new_bin_penalty + lookahead_reward + last_chance_bonus + density_adjustment
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic-Weighted Best-Fit
    // We aim to minimize post_residual, but penalize "fragmentation" (small residues that cannot fit future items).

    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty: If post_residual is small but > 0, it's often wasted.
    // We penalize values that are smaller than the smallest likely future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Logic: If the next item is large, favor bins that preserve space for it.
    // If the current post_residual is just below the next_item_size, it's a poor fit.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        } else if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= 5.0;
        }
    }

    // 3. Open Bin Management: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), add a threshold cost.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Only open a new bin if the mean_residual is already very tight (high fragmentation risk)
        // or if we have no other choice.
        score += 30.0 + (mean_residual * 0.5);
    }

    // 4. Harmonic Scaling: Favor bins that reach specific capacity thresholds (e.g., 50, 33, 25).
    // This helps pack items into "perfect" harmonic fractions.
    let harmonic_bonus = match post_residual {
        0 => -10.0, // Perfect fit
        r if r % 25 == 0 => -5.0,
        _ => 0.0,
    };
    score += harmonic_bonus;

    // 5. Progression Bias: As we approach the end of the stream, tighten the criteria.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
