        } else if post_residual < next_item_size {
            // Heavy penalty for stranding a large next item
            score += 40.0;
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin, penalize it based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0);
        // If we have fitting bins, opening a new one is a last resort.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tight Fit Bias: Reward bins that are already nearly full (Best Fit principle).
    // This minimizes the number of "half-empty" bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= (fill_ratio * 10.0);

    // 5. Mean residual balancing: Prefer bins that keep the overall mean residual stable.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) core: prioritize smaller post_residual
    // This naturally favors bins that become "tightly packed".

    // 2. Lookahead Penalty: If post_residual is smaller than the next item, 
    // it creates "dead space" that cannot be filled by the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 3. New Bin Penalty: Heavily penalize opening a new bin unless the current
    // fitting options are extremely poor (i.e., they create large dead space).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
