    // about filling existing bins to reduce the total count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // As we reach the end, prioritize filling bins completely (lower post_residual)
        score -= (1.0 - progress) * 10.0;
    }

    // 5. Balance the mean residual: Avoid filling bins that are already significantly
    // tighter than the average, effectively trying to keep bin residuals uniform.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res_f = post_residual as f64;

    // Penalize small residuals that are too small to fit common future items (the "fragmentation trap").
    // We target a "sweet spot" for post_residual relative to the mean residual of current bins.
    let residual_deviation = (post_res_f - mean_residual).abs();

    // Non-linear coupling: As the stream progresses, prioritize tighter fits (lower post_residual).
    // We use a power function to penalize larger residuals more heavily as the stream nears completion.
    let base_score = post_res_f.powf(1.2 + (0.5 * progress));

    // Lookahead logic: If the next item is large, avoid leaving a residual that is smaller than it.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 2.5
    } else {
        0.0
    };

    // New bin strategy: If this is an empty bin (bin_residual == bin_capacity), 
    // assign a baseline score that encourages using existing bins unless the fit is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // As we reach the end of the stream, opening a new bin is heavily penalized.
        // If we have many open bins, opening another is less desirable.
        (45.0 + (open_bins_count as f64 * 2.0)) * (1.0 + progress)
    } else {
        0.0
    };

    // Favor bins that maintain a residual close to the mean to keep bin packing density uniform.
    let uniformity_bonus = residual_deviation * 0.3;

    base_score + lookahead_penalty + new_bin_penalty + uniformity_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
