pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin heavily in the early/mid stages, 
    // but relax the constraint as we approach the end of the stream.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 50.0 + (open_bins_count as f64 * 2.5)
    } else {
        0.0
    };

    // Reward placements that leave very little space (Best-Fit principle).
    // The cubic term penalizes large gaps (fragmentation) severely.
    let fit_score = post.powi(3) / 100.0;

    // Lookahead logic: if next_item_size is large, avoid leaving small residuals
    // that won't fit the next item.
    let lookahead_penalty = if next_item_size > 0 {
        if post < next_item_size as f64 && post > 0.0 {
            (next_item_size as f64 - post) * 1.5
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Use mean_residual to balance the bin load. If current bin's post_residual
    // is significantly better than the global average, reward it.
    let balance_incentive = (post - mean_residual) * 0.5;

    // If this is the only bin that can fit, prioritize it to avoid creating 
    // unreachable space in other bins.
    let critical_fit_incentive = if fitting_bins_count == 1 && !is_new_bin {
        -20.0
    } else {
        0.0
    };

    fit_score + new_bin_penalty + lookahead_penalty + balance_incentive + critical_fit_incentive
}

