            // Penalize bins that would force a new bin for the next item
            score += 5.0;
        }
    }

    // Dynamic pressure: As the stream progresses, become more aggressive in packing
    // to keep the number of open bins low.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += (1.0 - progress) * (fill_ratio * 10.0);

    // If this is the only bin that can fit the item, prioritize it to avoid
    // unnecessary bin creation unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin (bin_residual == bin_capacity)
    // unless the fit in existing bins is prohibitively inefficient.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

