    }

    // 5. Progression Scaling: As the stream nears completion, tighten the constraints 
    // to force higher density in remaining bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    // 6. Harmonic Class Bias: Favor bins where the post_residual is a multiple 
