pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // We want to minimize post_residual, so lower values are naturally preferred.
    let mut score = post;

    // Penalty for creating a "sliver" (space too small for common items).
    // If the post_residual is small but > 0, it is often a "bad" fit.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - post / 10.0);
    }

    // Dynamic Lookahead Coupling:
    // If the next item is large, we want to prioritize keeping larger residuals.
    // If next_item_size is 0, we are near the end, prioritize closing bins.
    if next_item_size > 0 {
        let lookahead_pressure = (next_item_size as f64) / (bin_capacity as f64);
        score += lookahead_pressure * (bin_capacity as f64 - post) * 0.5;
    } else {
        // Near the end of the stream, favor filling bins to the brim.
        score -= (bin_capacity - post) as f64 * 0.2;
    }

    // Global state optimization:
    // If fitting_bins_count is 1, this bin is the "last resort". 
    // We penalize opening a new bin (bin_residual == bin_capacity) heavily
    // unless the current fit is extremely poor (post_residual is very high).
    if bin_residual == bin_capacity {
