    };

    // Calculate "Best Fit" base: prioritize minimizing post_residual (Best Fit Decreasing logic)
    // We add a penalty for "Dead Space" (residual < 10) that cannot fit any further items easily.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        15.0 - (post_residual as f64 * 1.5)
