    // Lookahead logic: if the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Global state: if we are near the end of the stream, be more aggressive about filling bins (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // Dynamic constraint: Avoid opening a new bin unless necessary.
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very high (meaning we have plenty of space elsewhere)
        // or if there are no bins that can fit the current item effectively.
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can fit it.
            score += 100.0 + (mean_residual * 0.5);
        } else {
            // It is the only option, make it attractive.
            score -= 10.0;
        }
    } else {
        // Reward bins that have residuals close to the mean_residual to keep density uniform.
        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
