        score += 20.0;
    }

    // Progression scaling: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": residuals too small for typical items (e.g., < 10)
    // are highly undesirable unless the bin is nearly full.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Encourage Best-Fit behavior: favoring bins that result in smaller residuals.
    // However, if the residual is 0, we reward it heavily as it is perfectly packed.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Pressure factor: if there are many open bins, we penalize opening a new one.
    // A new bin is identified by bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 1.5;
        // Penalize opening a new bin if other bins could have fit the item.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Lookahead logic: If the next item is large and this bin can't fit it,
    // we prefer a placement that leaves enough room for the next item if possible.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // This bin will likely be unable to accommodate the next item.
            score += 5.0;
        } else {
            // This bin is a candidate for the next item.
            score -= 5.0;
        }
    }

    // Global efficiency: if the mean residual is high, we are being inefficient.
    // Try to force tighter packing when the average bin is mostly empty.
    score += mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for future items.
    // If post_residual is small but > 0, it's often better to have it be 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
