    // 2. Aggressive Lookahead Matching:
    // If next_item_size is known, favor bins where the post_residual is closest to next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;
