    // 3. Balance with Global State:
    // Avoid opening new bins if there are existing bins with residuals close to the mean.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin proportional to the number of current bins
        // and how well packed they are on average.
        score += (open_bins_count as f64 * 5.0) + mean_residual;
    } else {
        // Reward bins that keep the residual close to the mean to maintain homogeneity.
        let deviation_from_mean = (post_residual as f64 - mean_residual).abs();
        score -= deviation_from_mean * 0.2;
    }

    // 4. Criticality Handling:
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. Progression Scaling:
    // As we reach the end of the stream, prioritize filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating small, unusable gaps (the "fragmentation" trap).
    // Gaps between 1 and 9 are usually hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: If the next item fits into the post-residual space, 
    // prioritize this bin to preserve bin packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Dynamic threshold for opening new bins:
    // As the stream progresses, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We only open a new bin if the mean residual of current bins is high (bad utilization)
        // or if we have very few fitting options.
        score += 25.0 + (mean_residual * 0.5) + (progress * 20.0);

        if fitting_bins_count == 0 {
            score -= 100.0; // Forced to open a new bin.
        }
    } else {
        // Prefer bins that are already "tight" to keep open bins count low.
        score += (open_bins_count as f64 * 0.1);

        // If this is the last chance for this item, reduce penalty to avoid unnecessary new bins.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Favor filling bins closer to capacity (Best Fit principle).
    score += (100.0 - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

