    // Penalize higher post_residual (creating wasted space).
    let mut score = post_res;

    // Favor bins that leave very little space (tight fit) as we approach the end of the stream.
    // As progress increases, we become more "picky" about leaving large gaps.
    score += (post_res * post_res) * (0.5 + 0.5 * progress);

    // If this is a new bin (bin_residual == bin_capacity):
    // Only choose a new bin if the fitting_bins_count is low or if the current 
