        score -= (item_size as f64 * 0.5);
    } else {
        // Reward bins that keep the mean residual of the system low.
        // This encourages "leveling" the residuals across active bins.
        score += (post_res - mean_residual).abs() * 0.5;
    }

    // Lookahead logic: if the next item is large and this bin can't fit it, 
    // penalize this bin slightly to keep it open for smaller future items.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_res) * 0.2;
    }

    // Critical constraint: If this is the last fitting bin, prioritize it to avoid 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
