        0.0
    };

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice.
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Reward bins that keep the mean residual balanced, preventing fragmentation
    let balance_reward = (post_res - mean_residual).abs() * 0.1;

    // Favor opening a new bin only if fitting_bins_count is low and we are early in the stream,
    // or if the current best fit is extremely poor (large post_residual).
    let new_bin_bias = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0 // Must open
        } else {
            // Expensive to open a new bin; only do it if the current fit is terrible
            45.0 + (progress * 20.0)
        }
    } else {
        0.0
    };

    // Final score: minimize post_residual (Best Fit), but add penalties for bad fragmentation
    // and lookahead mismatches.
    post_res + dead_space_penalty + lookahead_penalty + balance_reward + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a 'dead zone' (residual space too small for most items)
    // We define an aggressive dead zone threshold at 10 (minimum item size is typically 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next_item_size is known, penalize bin if it cannot accommodate it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that maintain perfect alignment for the next item
            score -= (post_residual - next_item_size) as f64 * 0.1;
        }
    }

    // Harmonic Class Logic: Reward bins that keep residuals near common multiples of 20 or 25
    // This helps pack items like 20, 25, 33, 50 more efficiently
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // If this is the only bin that fits, we are forced to take it, but penalize if it's a poor fit
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 100.0; // Overrides the dead-zone penalty to force acceptance
    }

    // New bin bias: only open a new bin if the current options are extremely poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high to encourage filling existing ones
        score = 45.0 + (mean_residual * 0.5);
    }

    // Progression scaling: As we reach the end of the stream, be more conservative with residuals
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
