pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Heavily favor bins that leave the smallest residual (standard Best-Fit logic)
    // We keep the post_residual as the base score.

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, reward this bin.
    // This effectively implements a Best-Fit Decreasing/Lookahead hybrid.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation Avoidance: If the post_residual is too small to fit any likely item 
    // (assuming 25 as a rough lower-bound threshold for small items), penalize it 
    // unless it is exactly 0 (perfect fit).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // 4. Scarcity Management: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. New Bin Threshold: If considering a new bin, apply a threshold based on 
    // how well the item fits in existing bins. If we have many open bins, 
    // opening a new one is expensive.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
