    // The penalty is non-linear: very small residuals are often worse than slightly larger ones.
    let waste_penalty = if post_res > 0.0 && post_res < 10.0 {
        25.0 / (post_res + 0.1)
    } else {
        post_res
    };

    // Factor in the lookahead: if the next item is large, 
