        score += 25.0; // Base penalty for opening a new bin
        if mean_residual > 20.0 {
            score -= 30.0; // Discount new bin if existing bins are already too fragmented
        }
    }

    // 4. Fitting Constraint: 
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Progression Bias:
    // As we reach the end of the stream, prioritize tighter packing (minimize post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalize new bin creation early, but become more lenient as the stream progresses
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress).powf(0.5);
    }

    // Best-fit/Worst-fit hybrid: 
    // If post_residual is very small (< 5), it's a tight fit (highly desirable).
    // If post_residual is large, we prefer to save space for larger future items.
    if post_residual < 5 {
        score -= 15.0; 
    } else if post_residual > 40 {
        score += 5.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If current bin can fit the next item after this one, give it a bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Global state awareness:
    // If we have many open bins, penalize opening another one.
    // If mean_residual is high, we have fragmented space; prioritize filling existing bins.
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * 0.5;
        score += (mean_residual - post_residual as f64) * 0.1;
    }

    // If this is the only bin that can fit the item, prioritize it strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base score is the post-placement residual. 
    // We want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often worse than having 0 residual (perfect fit).
    // Penalize small gaps that are hard to fill later.
    if post > 0.0 && post < 15.0 {
        score += 20.0 * (1.0 - post / 15.0);
    }

    // Lookahead coupling: If next_item_size is large, favor bins that can accommodate it.
    // If next_item_size fits in current post_residual, reward this bin.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 15.0 * (next_item_size as f64 / 100.0);
    }

    // Dynamic thresholding based on stream progress:
    // As the stream progresses, become more aggressive about filling bins (Best Fit)
    // and less willing to open new bins.
    if residual == bin_capacity as f64 {
        // This is a new bin candidate. 
        // Penalize opening a new bin increasingly as we reach the end of the stream.
        score += 40.0 * progress.powf(0.5);

        // If there are other bins that could fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0 * (1.0 - progress);
        }
    } else {
        // For existing bins, reward bins that are closer to the mean_residual
        // to keep bin utilization balanced.
        let deviation = (residual - mean_residual).abs();
        score -= 5.0 * (1.0 - (deviation / 100.0));
    }

    // Final non-linear scaling: penalize high open_bins_count to encourage packing
    // into fewer bins, but soften this penalty as the stream nears completion.
    score += (open_bins_count as f64).powf(1.2) * (1.0 - progress * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic 1306: Harmonic-Residual Balancing
    // We prioritize keeping the post_residual small (Best Fit), but penalize 
    // residuals that create "dead zones" (e.g., < 10) that cannot fit future items.

    let mut score = post_residual as f64;

    // 1. Dead-space penalty: If post_residual is small but > 0, it's often wasted space.
    // We penalize residuals in the [1, 9] range as they are too small for most items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead compatibility: If the next item fits into the post_residual, 
    // we reward this placement significantly to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Harmonic class alignment: Favor bins where the new residual is a 
    // multiple of common item sizes (20, 25, 33), as these are highly versatile.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 4. Global Load Balancing: Avoid opening too many bins early.
    // If we are at the beginning of the stream, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress.
        // It's cheaper to open a new bin early than late.
        score += 40.0 - (progress * 20.0);
    }

    // 5. Fitting constraint: If this is the only bin that fits the item, 
    // lower the score to force usage of existing capacity.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Mean residual pressure: If the current bin is "better than average" 
    // in terms of remaining space, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // If post_residual is in the range [1, 9], it is highly likely to be wasted (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 / (post_residual as f64);
    }

    // 2. Open Bin Pressure: Discourage opening new bins if we have many bins already
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty based on current usage.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we are near the end of the stream, prioritize closing current bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 3. Lookahead / Next Item Coupling: If we know the next item, prioritize bins 
    // that leave enough room for the next item, or fill bins that have just enough room.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: This bin can accommodate the next item.
            score -= 25.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Poor: This bin will be unable to fit the next item.
            score += 10.0;
        }
    }

    // 4. Fitting Constraint: If this is the last bin that fits, prioritize it to keep other
    // bins open for potential better matches later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Mean residual balancing: Penalize placing in bins that deviate significantly from the mean.
    // We want to keep residuals somewhat uniform to maintain flexibility.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
