}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual, which we want to minimize (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress. 
    // Early in the stream, we are more conservative; late in the stream, we are more aggressive.
    if is_new_bin {
        score += 25.0 + (progress * 40.0);
    }

    // Dynamic penalty for creating "dead space" (small residuals that are hard to fill).
    // If post_residual is small but > 0, it is often worse than 0 (Best Fit).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: If a second item is coming, try to preserve space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= (bin_capacity - (post_residual - next_item_size) as f64).sqrt();
        } else {
            // Penalize bins that leave just enough space to be unusable for the next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Interaction with global bin state:
    // If we have many open bins, penalize opening another one.
    if is_new_bin {
        score += (open_bins_count as f64).sqrt() * 5.0;
    }

    // If this is the only bin that fits, prioritize it strongly to avoid unnecessary new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
