pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Penalty for creating small, unusable slivers (the "fragmentation" penalty)
    // We penalize residuals that are small but not zero, as they are hard to fill.
    let fragmentation_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powf(1.5)
    } else {
        0.0
    };

    // Lookahead logic: Reward placing an item in a bin if the next item fits 
    // snugly into the remaining post_residual (Best Fit synergy).
    let lookahead_bonus = if next_item_size > 0 && (post as u32) >= next_item_size {
        let fit_quality = (post - next_item_size as f64) / capacity;
        fit_quality * -10.0
    } else {
