    };

    // Use mean_residual to balance packing density.
    // If the current bin's post_residual is significantly better than the mean, favor it.
    let density_score = (post - mean_residual) * 0.2;

    // Final score: Lower is better.
    // post^2 penalizes large gaps (Best Fit approximation).
    // fragmentation_penalty discourages useless small gaps.
    // lookahead_bonus encourages "perfect" pair packing.
    post.powf(1.8) + fragmentation_penalty + lookahead_bonus + new_bin_penalty + density_score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
