pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post_residual (Best Fit principle).
    // Penalize large post_residual values quadratically to avoid "fragmentation".
    let mut score = post * post * 0.01;

    // Lookahead logic: If the next item fits into the current post_residual,
    // strongly incentivize this bin to preserve future packing efficiency.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
