    // Dynamic pressure: As the stream nears the end, become more conservative 
    // about opening new bins to prevent straggler items.
    if bin_residual == bin_capacity {
        // New bin penalty: increases as we approach the end of the stream.
        score += 25.0 + (progress * 50.0);
    } else {
        // If this is the only bin that fits the current item, prioritize it 
        // to avoid wasting capacity in other bins or force-opening a new one.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Entropy control: Penalize bins that deviate significantly from the mean_residual
    // of all open bins to keep the "load" balanced across the bin set.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
