pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let capacity = bin_capacity as f64;

    // Core objective: Minimize waste (post_residual).
    // Penalize creating "dead space" (post_residual < 10) that is hard to fill later.
    // Reward bins that maintain a high density relative to the mean_residual.

    let mut score = post;

    // Penalty for creating a new bin: if this is a new bin (residual == capacity),
    // heavily penalize it unless no other bin can fit the item or we are late in the stream.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 20.0);
    } else {
        // Non-linear penalty for creating small gaps that are likely unusable.
        // If post_residual is in the "danger zone" (1..10), increase score.
        if post_residual < 10 {
            score += (10.0 - post) * 5.0;
        }

        // Coupling with lookahead: if next_item_size exists, penalize bins that 
        // would leave too little room for the next item.
        if next_item_size > 0 {
            if post < next_item_size as f64 {
                score += 30.0;
            }
        }
    }

    // Interaction with global state: favor bins that keep the mean_residual 
    // balanced to prevent fragmentation across many bins.
    let residual_bias = (post - mean_residual).powi(2) * 0.1;
    score += residual_bias;

    // Favor bins that are "almost full" if they can fit the item, 
    // but only if they don't fall into the extreme fragmentation trap.
    score -= (capacity - residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
