    // We prefer post_residual to be as small as possible.
    let mut score = post_residual as f64;

    // 2. Dead Space Penalty: If the remaining space is too small to fit the smallest expected items (approx 10),
    // it is "wasted" space. Penalize residuals in the (0, 10) range heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 20.0;
    }

    // 3. New Bin Penalty: Discourage opening new bins unless necessary or optimal.
    if is_new_bin {
