        // Penalty decreases as the game progresses (desperation mode).
        score += 50.0 * (1.0 - progress) * (fitting_bins_count as f64 + 1.0);
    }

    // 4. Lookahead Coupling: If a future item is large, avoid small post_residuals 
    // that might force a new bin later.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 5. Open Bin Pressure: If we have many open bins, prioritize closing them 
    // by preferring bins with smaller post_residuals (already in base score) 
