    score += (open_bins_count as f64) * 0.5;

    // 6. Mean Residual Balancing: If this bin's residual is significantly higher than
    // the mean, it might be a "dangling" bin. Penalize deviations.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
